export const VIEW_CSS = "/* Harny — the panel's stylesheet.\n   Extracted from view-html.ts, where it lived inside a template literal one stray backtick away\n   from a syntax error. It is inlined into the page through the generated module\n   src/chat/view-css.ts (scripts/gen-view-css.mjs, run before every bundle).\n   Formatted by prettier (`npm run format`); the CSS-pinning tests normalise whitespace, so a\n   rule can be reflowed without breaking them. */\n/* ⚠ THE TEXT SCALE IS NOT DECLARED ANYWHERE (found 2026-11-11, present since the file was created):\n   this sheet USES `--fs-xs/sm/md/lg/xl` 165 times and declares NONE of them, and no other file does\n   either — checked through the whole history, it was never declared. `font-size: var(--fs-xs)` is\n   therefore INVALID, the declaration is dropped, and every one of those rules silently renders at\n   the inherited 1rem. Nothing breaks visibly (a uniform 1rem is still consistent), which is why it\n   survived: it was caught only when a number box, sized in rem against the scale that never\n   applied, came out narrower than the digits it had to show. Left as-is ON PURPOSE — declaring the\n   scale now would shrink most of the panel in one go and needs a deliberate pass of its own.\n   Until then: size FONT-RELATED boxes in `ch`, never against the scale. */\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n/* ONE sphere for every round knob in the panel (slider thumbs, the MCP switch's dot): lit\n   at the top-left, a shade darker at the bottom-right, resting on a soft shadow. Defined\n   here, once, so a knob looks like a knob wherever it appears — and so \"more shadow\" is a\n   single number, not a hunt through the sheet. */\n:root {\n  --knob-sphere: radial-gradient(circle at 34% 30%, #ffffff 0%, #ededed 55%, #bdbdbd 100%);\n  --knob-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);\n}\n/* ── THE SLIDER: one appearance, ten controls ──\n   Every range input in the panel — context window, output tokens, the three sampler knobs, the\n   parallel count, the Loop Guard parameters, the two compaction knobs, the two History-vacuum\n   knobs — is painted HERE and nowhere else: a thin rounded bar with the ORANGE fill left of the\n   knob, and the knob itself drawn by us (`accent-color` can colour the native thumb but cannot\n   shade it). Both engines' parts are here, or the slider would look native in one and custom in\n   the other.\n\n   What a call site MAY do: size the control — `flex`, `width`, `grid-area`, `min-width`. What it may\n   NOT do: repaint it. Three sites used to repeat `accent-color` (dead once the thumb is drawn by\n   us), plus `height`, `margin`, `cursor` and `:disabled` copied from these rules; that is how one\n   control grows four looks. The VALUE RANGE is per slider by nature (min/max/step are data, set in\n   the markup), and the fill follows the value on its own: view.ts reconciles `--fill` for every\n   range input after any input/change/click and after every host message, so there is no per-slider\n   wiring to forget. */\ninput[type=\"range\"] {\n  -webkit-appearance: none;\n  appearance: none;\n  background: transparent;\n  height: 14px;\n  margin: 0;\n  cursor: pointer;\n}\ninput[type=\"range\"]::-webkit-slider-runnable-track {\n  height: 4px;\n  border-radius: 999px;\n  /* Filled LEFT of the knob in the accent, neutral to the right: --fill is written by the\n     view whenever the value moves (WebKit has no ::-slider-progress). */\n  background: linear-gradient(to right, var(--accent) 0 var(--fill, 0%), var(--overlay-3) var(--fill, 0%) 100%);\n}\ninput[type=\"range\"]::-webkit-slider-thumb {\n  -webkit-appearance: none;\n  appearance: none;\n  width: 14px;\n  height: 14px;\n  margin-top: -5px;\n  border: none;\n  border-radius: 50%;\n  /* A plain ORANGE circle with the same shadow as every other knob (a composed gradient\n     custom property on this pseudo-element was dropped as invalid and only its rim stayed). */\n  background: var(--accent);\n  box-shadow: var(--knob-shadow);\n}\ninput[type=\"range\"]::-moz-range-track {\n  height: 4px;\n  border-radius: 999px;\n  background: var(--overlay-3);\n}\n/* Firefox HAS a progress pseudo-element: no --fill needed on this side. */\ninput[type=\"range\"]::-moz-range-progress {\n  height: 4px;\n  border-radius: 999px;\n  background: var(--accent);\n}\ninput[type=\"range\"]::-moz-range-thumb {\n  width: 14px;\n  height: 14px;\n  border: none;\n  border-radius: 50%;\n  background: var(--accent);\n  box-shadow: var(--knob-shadow);\n}\ninput[type=\"range\"]:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n/* ── THE SWITCH: the panel's ONE on/off control ──\n   Every toggle in Harny is this pill, and every toggle in Harny gets it from HERE — a stylesheet\n   rule per call site is how the same question ended up with four looks (a pill in the tools\n   popover, a 15px checkbox in the MCP form, an 11px tick next to \"Include response\", a 9px radio\n   beside it). The module is src/chat/webview/switch.ts; this is its only appearance.\n\n   TWO DOM SHAPES, ONE RULE: a <button role=\"switch\" aria-checked=\"true|false\"> and a native\n   <input type=\"checkbox\" class=\"harny-switch\"> are answered by the same declarations, because the\n   shapes differ only in where the state lives (:checked vs the attribute). A native input keeps its\n   label click, its keyboard toggle and its `checked` property; appearance:none is the ONLY thing\n   that stops it from being painted by the browser.\n\n   Geometry: the TRACK is exactly as tall as the knob (no slack above/below it), so the switch reads\n   as one solid piece at 12px tall, and the travel (14px) is track − knob. The knob is the same\n   `--knob-sphere` as the slider thumbs: one light source for every round thing in the panel. */\n.harny-switch {\n  position: relative;\n  display: block;\n  flex: none;\n  width: 26px;\n  height: 12px;\n  min-width: 0;\n  min-height: 0;\n  padding: 0;\n  margin: 0;\n  /* A native checkbox obeys the browser until this line: -webkit- for Electron, appearance for the\n     standard. Both, or the input keeps its box and the knob has nowhere to sit. */\n  -webkit-appearance: none;\n  appearance: none;\n  /* OFF: a WHITE veil on the dark theme (--overlay-* is white-alpha here and black-alpha on paper,\n     so the same rule reads as a light grey track in both). */\n  border: none;\n  border-radius: 999px;\n  background: var(--overlay-3);\n  /* The button chrome (3D borders, filter, shadow) belongs to BUTTONS: a pill has none of it. */\n  box-shadow: none;\n  filter: none;\n  cursor: pointer;\n  transition: background 0.12s ease;\n}\n.harny-switch::after {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 12px;\n  height: 12px;\n  /* A dot must contrast with ITS track: grey on the white veil (the \"off\" look)… */\n  border-radius: 50%;\n  background: var(--muted-2);\n  transition:\n    transform 0.12s ease,\n    background 0.12s ease;\n}\n/* …ON: the TRACK is the accent and the DOT is WHITE with a small radial gradient — lit from the\n   top-left, a shade darker at the bottom-right, plus a hairline shadow underneath — so it reads as\n   a tiny sphere instead of a flat sticker. One literal value for both themes: white sits on either\n   terracotta. */\n.harny-switch[aria-checked=\"true\"],\n.harny-switch:checked {\n  background: var(--accent);\n}\n.harny-switch[aria-checked=\"true\"]::after,\n.harny-switch:checked::after {\n  transform: translateX(14px);\n  background: var(--knob-sphere);\n  box-shadow: var(--knob-shadow);\n}\n/* A switch that cannot be flipped (a run in flight, a tool with nothing to allow) says so instead of\n   ignoring the press. */\n.harny-switch:disabled {\n  opacity: 0.3;\n  cursor: default;\n}\n/* Keyboard users get the same ring as the other controls, drawn OUTSIDE the pill: the pill has no\n   border to thicken and an inset ring would fight the knob. */\n.harny-switch:focus-visible {\n  outline: 1px solid var(--accent);\n  outline-offset: 2px;\n}\n/* UI: one sans family everywhere (inherited); only real code/diff\n   content switches to the single mono family. Grouped selectors so every\n   element — including form controls, which do NOT inherit by default —\n   takes its family from these two central rules. */\nbody,\nbutton,\ninput,\nselect,\ntextarea {\n  font-family: var(--font-ui);\n}\npre,\ncode,\n.code-lang,\n.fd-stat,\n.fd-body,\n.sm-folder,\n.srow-folder {\n  font-family: var(--font-mono);\n}\n/* Never squeeze the LAYOUT below this: past it the panel gets a horizontal\n   scrollbar instead of compressing the controls. (The PANEL's own minimum\n   width is controlled by VS Code — the extension cannot force it: this floor\n   is what Harny guarantees about its CONTENT, and it is also why the layout\n   looks the same every time it opens.)\n   450px is the MEASURED minimum, read off a live width readout in a real VS\n   Code panel: the narrowest width at which the prompt placeholder still fits\n   on one line and the control row (Analyze / Queue / Parallel / AI Model) is\n   not squeezed. The floor shipped is PANEL_REFERENCE_WIDTH (panel-width.ts),\n   keeping ~50px (about a ninth) of margin over that measurement — that margin\n   is the TOLERANCE you feel when dragging the panel narrower before the\n   scrollbar appears. The px value comes from that constant, NOT from a\n   literal here: the intended tolerance and what the stylesheet enforces must\n   never drift apart.\n   (How wide the panel OPENS is VS Code's, not ours — it restores the width\n   you last left it at, and offers no API to read or set it.)\n   The 32rem part is INDEPENDENT of the reference: it covers LARGER editor\n   fonts, where every control grows. Headless measurements put that side at\n   roughly 22.75px per font px plus ~148px of chrome (~510px at a 16px font,\n   ~600px at 20px), rounded up to 32 per font px to stay on the conservative\n   side. With the floor at 500px the rem side takes over past a ~15.6px font\n   (32rem === 500px exactly there).\n   Beware: those headless numbers ran ~6% high against the real panel (they\n   said 480px where the real answer is 450px), so treat the rem part as the\n   conservative side of an estimate and the px part as the measured one.\n   This also clears the two things measured earlier: the control row\n   overflows under ~407px and the transcript action pills reach the centred\n   ctl-toggle chevron under ~379px (at 14px) — both well below the floor. */\nhtml {\n  min-width: var(--panel-min-width);\n  overflow-x: auto;\n  height: 100%;\n}\nbody {\n  font-size: 1rem;\n  background: var(--bg);\n  color: var(--fg);\n  /* 100%, NOT 100vh. When the panel goes under the floor above, the window\n     grows a HORIZONTAL scrollbar and that bar eats ~15px of height; 100vh is\n     measured WITHOUT scrollbars, so the body ended up ~15px taller than the\n     area actually drawn and the panel grew a SECOND, vertical bar — the extra\n     bar on the window that used to appear. A percentage always matches\n     the viewport the panel is drawn in. */\n  height: 100%;\n  /* Relative so the modal overlays are laid out against the PANEL CONTENT\n     (this box, which honours the min-width floor) instead of the viewport:\n     that is what keeps a dialog from being squeezed by the visible slice\n     when the horizontal bar is showing, and what makes it scroll together\n     with the panel. No absolute child of body relied on the initial\n     containing block: they all sit inside their own positioned parents. */\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  min-width: var(--panel-min-width);\n}\n\n/* Sessions area: a card matching the control cards below. Borderless:\n   separation comes from the tone-on-tone surface, not outline lines. */\n.sessions-card {\n  border-radius: 8px;\n  /* The bottom margin is the whole gap above the tab strip: #tabs only adds\n     its own 5px of padding-top, so the session card and the tab head used\n     to sit 5px apart (identical open or collapsed, since collapsing hides\n     #sessions and leaves just the header). */\n  margin: 8px 10px 10px;\n  background: var(--input-bg);\n  overflow: hidden; /* keep the scrolling list inside the rounded corners */\n  flex-shrink: 0;\n}\n/* NO rule under the title: the card is one tone-on-tone surface, so the header is\n   separated from the search row and the list by SPACE, not by an outline line. */\n#session-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 5px 10px;\n  font-weight: 700;\n  font-size: var(--fs-md);\n  color: var(--fg-strong);\n  cursor: pointer;\n  user-select: none;\n}\n/* ── ONE fold chevron, ROTATED ──\n   Every fold used to swap the TEXT glyph \"▶\" (closed) for \"▼\" (open): a filled triangle changes\n   shape and weight as it opens, and it reads heavier than the chevrons the rest of the panel\n   already uses (#ctl-toggle-btn, .mode-btn-chevron, .lg-collapse). Here the state is a class on\n   ONE svg and the CSS turns it: right when closed, down when open. The box never changes, so\n   nothing shifts, and the turn is the same 0.15s the other folds use. */\n.toggle,\n.tool-toggle {\n  width: 12px;\n  flex-shrink: 0;\n  color: var(--muted);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n.toggle > .toggle-chevron,\n.tool-toggle > .toggle-chevron {\n  display: block;\n  transform: rotate(-90deg);\n  transform-origin: center;\n  transition:\n    transform 0.15s ease,\n    color 0.15s ease;\n}\n.toggle.is-open > .toggle-chevron,\n.tool-toggle.is-open > .toggle-chevron {\n  transform: rotate(0deg);\n}\n/* A fold you can click says so: the chevron takes the header's hover colour. */\n.tool-header:hover .toggle-chevron,\n.thinking-header:hover .toggle-chevron,\n#session-head:hover .toggle-chevron,\n#pending-head:hover .toggle-chevron {\n  color: var(--accent);\n}\n#session-head .toggle {\n  font-size: var(--fs-xs);\n}\n#session-head .spacer {\n  flex: 1;\n}\n#session-head button {\n  background: transparent;\n  border: none;\n  color: var(--accent);\n  font-size: var(--fs-xl);\n  cursor: pointer;\n  padding: 0 4px;\n  border-radius: 4px;\n  transition: background-color 0.12s;\n}\n#session-head button:hover {\n  background: var(--overlay-1);\n}\n/* The gear keys share ONE look and size across every card (sessions head,\n   model row, compaction metrics): see the shared .gear-btn rule below. */\n#sessions {\n  overflow-y: auto;\n  max-height: 40vh;\n  padding: 4px 0 6px;\n}\n#sessions.hidden {\n  display: none;\n}\n.srow {\n  display: flex;\n  align-items: center;\n  gap: 3px;\n  padding: 4px 10px;\n  font-size: var(--fs-lg);\n  flex-wrap: wrap;\n  border-radius: 6px;\n  margin: 1px 4px;\n  transition: background-color 0.1s;\n}\n.srow:hover {\n  background: var(--tool-bg);\n}\n/* Creation + last-modified dates, on their own line BEFORE the name. */\n.srow .smeta {\n  flex: 1 1 100%;\n  color: var(--muted);\n  font-size: var(--fs-xs);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.srow .name {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  cursor: pointer;\n}\n.srow.open .name {\n  color: var(--accent);\n}\n/* An open session that lives in ANOTHER folder: listed so its tab is never\n   orphaned, dimmed so it never reads as one of this folder's. */\n.srow.foreign .name {\n  opacity: 0.75;\n  font-style: italic;\n}\n/* ── HOME row (no folder open): it CHOOSES a workspace ──\n   The whole row is the control, so it must read as one: a pointer, a focus ring,\n   Enter/Space. The folder path is the identifying fact in this state — it IS what you are\n   choosing — so it gets its own line in the mono face, and the trailing label says what\n   the click does before you commit to it (opening a folder reloads the window).\n   The only keys it carries are rename/delete: they act on the stored row BY ID, so they\n   need no working directory. Branch needs one (a copy is born in a folder), so it is not\n   here. */\n.srow.home {\n  cursor: pointer;\n  align-items: baseline;\n}\n.srow.home:focus-visible {\n  outline: 1px solid var(--accent);\n  outline-offset: -1px;\n}\n.srow-folder {\n  flex: 1 1 100%;\n  min-width: 0;\n  font-size: var(--fs-xs);\n  color: var(--muted-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.srow-folder.missing {\n  color: var(--error);\n}\n.srow-open {\n  flex: 0 0 auto;\n  font-size: var(--fs-sm);\n  color: var(--accent);\n  white-space: nowrap;\n}\n/* The home row's rename/delete sit at the END of the name line, after the \"Open session\"\n   label: they are secondary to the choice, and they must not push the folder path (the one\n   fact that identifies WHAT you are choosing) off its own line. */\n.srow.home .srow-actions {\n  flex: 0 0 auto;\n  margin-left: 8px;\n}\n/* A folder that is gone is named in the HERO too (home screen): the path is the one\n   fact that identifies WHAT is missing, so it sits in the mono face. */\n.empty-hero .folder-path {\n  font-family: var(--font-mono);\n  color: var(--fg-dim);\n}\n.srow-actions {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n.srow-actions button {\n  background: transparent;\n  border: none;\n  color: var(--fg);\n  font-size: var(--fs-lg);\n  cursor: pointer;\n  opacity: 0.65;\n  padding: 2px 4px;\n  border-radius: 4px;\n  transition:\n    opacity 0.12s,\n    color 0.12s,\n    background-color 0.12s;\n}\n.srow-actions button:hover:not(:disabled) {\n  opacity: 1;\n  color: var(--accent);\n  background: var(--overlay-1);\n}\n/* A working session is fully hover-inert: the row stops highlighting and\n   its action keys (branch/rename/delete) become dead — no cursor, no\n   hover reaction, no tooltip (pointer-events none). Mirrors the ⎇ policy\n   on assistant replies. */\n.srow.is-working:hover {\n  background: transparent;\n}\n.srow-actions button:disabled {\n  opacity: 0.28;\n  cursor: default;\n  pointer-events: none;\n}\n.empty {\n  padding: 12px;\n  text-align: center;\n  color: var(--muted);\n  font-size: var(--fs-lg);\n}\n\n/* Tabs: raised pill keys, consistent with the 3D button chrome. */\n#tabs {\n  display: flex;\n  gap: 3px;\n  padding: 5px 8px 0;\n  border-bottom: 1px solid var(--border);\n  flex-shrink: 0;\n  /* Horizontal scroll ONLY: no vertical scrollbar on a single-row strip. */\n  overflow-x: auto;\n  overflow-y: hidden;\n  /* Tabs do NOT shrink (they stay readable); the strip SCROLLS instead. A\n     thin, always-visible scrollbar + wheel-to-sideways make it reachable. */\n  scrollbar-width: thin;\n  scrollbar-color: var(--scroll-thumb) transparent;\n}\n#tabs::-webkit-scrollbar {\n  height: 6px;\n}\n#tabs::-webkit-scrollbar-track {\n  background: transparent;\n}\n#tabs::-webkit-scrollbar-thumb {\n  background: var(--scroll-thumb);\n  border-radius: 3px;\n}\n#tabs::-webkit-scrollbar-thumb:hover {\n  background: var(--scroll-thumb-hover);\n}\n.tab {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  padding: 4px 10px;\n  border-radius: 6px 6px 0 0;\n  cursor: pointer;\n  font-size: var(--fs-md);\n  white-space: nowrap;\n  color: var(--muted-2);\n  border: 1px solid transparent;\n  border-bottom: none;\n  background: linear-gradient(to bottom, var(--overlay-1), rgba(255, 255, 255, 0));\n  box-shadow: inset 0 -1px 0 var(--overlay-1);\n  transition:\n    color 0.12s,\n    background-color 0.12s,\n    box-shadow 0.12s;\n  /* Readable floor: never squeeze a tab below this (the strip scrolls). */\n  max-width: 12rem;\n  min-width: 5.5rem;\n  flex-shrink: 0;\n  /* sits flush on the strip's border (active covers it with its face) */\n  margin-bottom: -1px;\n  /* Dragging a tab must MOVE it, never select its name. */\n  user-select: none;\n}\n/* The label takes the FREE space, so the × sits on the tab's right edge instead of\n   hugging the end of the name. min-width 0 is what makes the ellipsis work: a flex\n   item refuses to shrink below its content without it. */\n.tab > span:first-child {\n  flex: 1;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.tab:hover:not(.active):not(.dragging) {\n  color: var(--fg);\n  background: linear-gradient(to bottom, var(--overlay-2), var(--overlay-1));\n}\n.tab.active {\n  color: var(--fg);\n  border-color: var(--border);\n  background: linear-gradient(to bottom, var(--overlay-3), var(--overlay-1)), var(--assistant-msg);\n  box-shadow:\n    inset 0 1px 0 var(--overlay-3),\n    0 -1px 3px var(--overlay-2);\n}\n.tab.active .close {\n  color: var(--fg-dim);\n}\n/* A tab whose folder is gone: the transcript still opens (a tab switch needs no root),\n   but the agent has nowhere to work — so the tab says so instead of looking healthy. */\n.tab.missing,\n.tab.missing .close {\n  color: var(--error);\n}\n.tab .close {\n  font-size: var(--fs-sm);\n  line-height: 1;\n  padding: 1px 3px;\n  margin-right: -2px;\n  border-radius: 4px;\n  color: var(--muted-2);\n  flex-shrink: 0;\n  transition:\n    color 0.12s,\n    background-color 0.12s;\n}\n.tab .close:hover {\n  color: var(--error);\n  background: rgba(244, 71, 71, 0.14);\n}\n/* A WORKING session's tab cannot be closed: its × is inert (switching the\n   tab stays allowed). */\n.tab .close.disabled {\n  opacity: 0.35;\n  pointer-events: none;\n}\n\n/* Dragging a tab to reorder the strip (view.ts uses POINTER events, not HTML5\n   drag & drop: that channel belongs to the file drops).\n\n   The GHOST is the dragged tab ITSELF, taken OUT of the flow: it follows the\n   pointer, lifted and slightly tilted, so it reads as held in the hand and the\n   strip shows where it came from. */\n.tab.dragging {\n  position: fixed;\n  z-index: 30;\n  margin: 0;\n  pointer-events: none;\n  cursor: grabbing;\n  opacity: 0.96;\n  color: var(--fg);\n  border-color: var(--border);\n  border-bottom: 1px solid var(--border);\n  border-radius: 6px;\n  background: linear-gradient(to bottom, var(--overlay-3), var(--overlay-1)), var(--assistant-msg);\n  box-shadow:\n    0 8px 20px rgba(0, 0, 0, 0.45),\n    inset 0 1px 0 var(--overlay-3);\n  transform: scale(1.04) rotate(-0.6deg);\n}\n/* The SLOT is where it will land: the tabs part around it, a dashed accent frame\n   fills the gap, and the solid bar on its leading edge is the \"lineetta\" that says\n   exactly where the tab drops. */\n.tab-placeholder {\n  position: relative;\n  flex-shrink: 0;\n  border-radius: 6px 6px 0 0;\n  margin-bottom: -1px;\n  border: 1px dashed var(--accent-line);\n  background: var(--accent-tint-soft);\n}\n.tab-placeholder::before {\n  content: \"\";\n  position: absolute;\n  left: -3px;\n  top: 2px;\n  bottom: -1px;\n  width: 2px;\n  border-radius: 1px;\n  background: var(--accent);\n  box-shadow: 0 0 6px var(--accent-glow);\n}\n/* While reordering: the whole strip shows the grabbing cursor and the tabs do\n   not repaint their hover state as the slot hops between them. */\n#tabs.reordering {\n  cursor: grabbing;\n}\n#tabs.reordering .tab {\n  transition: none;\n}\n\n/* Chat */\n/* The transcript's POSITIONED parent: the switching veil is an overlay, and\n   #messages itself must stay UNPOSITIONED (its children are measured with\n   getBoundingClientRect, and a containing block there would change what\n   \"viewport\" means for them). Same flex role #messages had as a body child. */\n#messages-wrap {\n  position: relative;\n  flex: 1;\n  /* CHAT FLOOR — the transcript is the ONE box that must never be squeezed\n     away. With a bare `flex-basis: 0` it had no claim on the panel height, so\n     an EXPANDED control stack (plus the open sessions card) could eat the\n     whole viewport and the transcript collapsed to zero: the pending bubbles\n     and \"Working…\" then landed right on the tab strip. A min-height keeps a\n     readable slice of chat whatever is open below it; the deficit is taken by\n     #status, which SCROLLS. 22vh makes the floor follow the panel (a tiny\n     window still shows the prompt and the metrics instead of being clipped),\n     9rem caps it on a normal-size panel. */\n  min-height: min(9rem, 22vh);\n  display: flex;\n  flex-direction: column;\n}\n/* scrollbar-gutter: stable reserves the scrollbar slot even when no\n   scrollbar is shown — the bubble column width stays IDENTICAL whether or\n   not the scrollbar appears. padding-right:0 lets the 10px gutter play the\n   role of the right margin, so the chat column matches the controls below\n   (same width, symmetric 10px gaps: paddings left 10 / gutter 10 right). */\n#messages {\n  flex: 1;\n  overflow-y: auto;\n  scrollbar-gutter: stable;\n  /* Top padding leaves room for the action tabs that slide UP out of the\n     first bubble (see .branch-at/.truncate-at); too little clips them. */\n  padding: 24px 0 0 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n/* Switching a session (view.ts showSwitchVeil): the transcript blurs behind a\n   small card while the new state is being built, with the accent arc turning.\n   Faded in with a DELAY on purpose: a switch that lands quickly must show\n   NOTHING — a spinner that flashes for 40ms is worse than no spinner at all. */\n#switch-veil {\n  position: absolute;\n  inset: 0;\n  z-index: 5;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  backdrop-filter: blur(2px);\n  opacity: 0;\n  transition: opacity 0.16s ease;\n  /* Never in the way: the transcript under it is about to be replaced anyway,\n     and a veil that eats clicks would only add a way to lose one. */\n  pointer-events: none;\n}\n#switch-veil.visible {\n  opacity: 1;\n  transition-delay: 0.12s;\n}\n.switch-card {\n  display: flex;\n  align-items: center;\n  gap: 9px;\n  padding: 7px 14px;\n  border-radius: 999px;\n  background: var(--input-bg);\n  border: 1px solid var(--border);\n  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);\n  color: var(--fg);\n  font-size: var(--fs-md);\n}\n.switch-spinner {\n  width: 14px;\n  height: 14px;\n  flex-shrink: 0;\n  border-radius: 50%;\n  border: 2px solid var(--accent-line);\n  border-top-color: var(--accent);\n  animation: switch-spin 0.7s linear infinite;\n}\n@keyframes switch-spin {\n  to {\n    transform: rotate(360deg);\n  }\n}\n.switch-label {\n  max-width: 16rem;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* Reduced motion: the card stays (the wait is still announced), the arc stops. */\n@media (prefers-reduced-motion: reduce) {\n  .switch-spinner {\n    animation: none;\n  }\n}\n.msg {\n  padding: 8px 10px;\n  border-radius: 8px;\n  max-width: 92%;\n  min-width: 0;\n  word-wrap: break-word;\n  word-break: break-word;\n  overflow-wrap: break-word;\n  line-height: 1.4;\n  font-size: var(--fs-lg);\n}\n/* pre-wrap only for plain-text bubbles (user messages); markdown bubbles\n   (assistant/tool) use breaks:true and white-space normal to avoid the\n   ghost blank lines produced by markdown's structural newlines. */\n/* The ✂ tab is ~26px wide anchored 8px from the right, so a one-character\n   message (bubble ≈ 28px) would be narrower than the tab and it would stick\n   out to the left. This floor keeps the tab inside the bubble. */\n.msg.user {\n  align-self: flex-end;\n  background: var(--user-msg);\n  color: #fff;\n  white-space: pre-wrap;\n  position: relative;\n  min-width: 48px;\n  text-align: center;\n}\n/* All four corners are the base bubble's 8px: a prompt is the plain lozenge, told apart by its\n   colour and its side. The mark beside it is the only thing that says who typed it (below), and\n   it hangs OUTSIDE the bubble — so `border-radius` is NOT restated for `.msg.user` anywhere, and\n   `.msg` is the one place that owns the shape. */\n/* ── THE SIGN-OFF: who typed it ──\n   A prompt the user wrote is closed by the person-round mark, hung OUTSIDE the bubble on\n   its right edge (view.ts `userAvatar`). Outside, not inside, because the bubble's width\n   is the message: a mark in the corner would either eat a line of text or push the bubble\n   away from the edge on every single prompt. So the bubble pays for the column with a\n   MARGIN equal to the mark + the gap, and the mark itself is positioned off the bubble's\n   own right edge — no wrapper element, no change to how `#messages` stacks, and no change\n   to the bubble's corners.\n   The mark is EXACTLY as tall as a one-line prompt: 8px of padding above + 8px below + one\n   line box (1.4 × the 16px it inherits). Written as that expression, not as 38px, so it\n   stays true if the type moves — and the gap is the same expression, so the two cannot\n   drift apart.\n   With that diameter the mark is also, by construction, centred on the FIRST line: the line\n   box runs from 8px to 8+1.4em, and the mark from 0 to 16+1.4em — same centre. So a\n   one-line prompt has it exactly level with the bubble, and a four-line one still has it at\n   the top beside the first line, never beside the third. (A `top: 50%` would re-centre it\n   on the bubble and lose that.) An attachment makes the bubble tall for a reason of its own\n   and changes nothing: the first line is still the first line.\n   The `max-width` is where the reserved column has to be PAID FOR, not just added: `.msg`\n   caps a bubble at 92% of `#messages`, and 92% + a 44px margin does not fit once the panel is\n   narrower than ~555px (the 8% left over stops covering the margin). `align-self: flex-end`\n   aligns the MARGIN box, so the shortfall lands on the bubble's LEFT — a long prompt would\n   bleed out of the transcript's left edge by a few pixels and, at the narrowest widths, out\n   of the panel. Same expression on both sides: the column is subtracted from the cap at the\n   same time as it is added to the margin.\n   Only the bubbles the user typed: the nudge and the checkpoint never get the class (view.ts\n   adds it in the prompt path and strips it in the checkpoint path). */\n.msg.user.has-avatar {\n  margin-right: calc(16px + 1.4em + 6px);\n  max-width: calc(92% - (16px + 1.4em + 6px));\n}\n.msg.user > .user-avatar {\n  position: absolute;\n  left: 100%;\n  top: 0;\n  width: calc(16px + 1.4em);\n  height: calc(16px + 1.4em);\n  margin-left: 6px;\n  display: block;\n  /* Quiet on purpose: it is a sign-off, not a badge. Same grey as the metadata under an\n     assistant reply, so the only ORANGE thing in the transcript stays the prompt. */\n  color: var(--muted-2);\n  /* Nothing to click and nothing to select: it sits beside text the user may be dragging. */\n  pointer-events: none;\n  user-select: none;\n}\n/* The artwork is drawn on a 24 grid with a size attribute of its own; here the CSS owns the\n   measure (one bubble tall), so the svg fills the box it was given. */\n.msg.user > .user-avatar > svg {\n  display: block;\n  width: 100%;\n  height: 100%;\n}\n/* The user text is a shrink-to-fit, LEFT-aligned block CENTERED in the bubble:\n   a single character sits in the middle of the min-width bubble; as the text\n   grows it reaches the bubble edges and stays left-aligned. */\n.msg.user > .user-text {\n  display: inline-block;\n  max-width: 100%;\n  text-align: left;\n  white-space: pre-wrap;\n}\n/* …BUT when the bubble is wide for a reason of ITS OWN — an attachment, which is\n   usually wider than the text — a shrink-to-fit block floats in the middle of it and\n   the message reads as if it were centred. With the marker, the text takes the full\n   width and starts where the previews do: the whole bubble reads left-aligned. */\n.msg.user.has-attachments > .user-text {\n  display: block;\n}\n/* Harness-injected prompts (loop guard / delegation / budget): a LIGHT-BLUE\n   bubble with a \"Nudge\" label, so they read as SYSTEM messages and can't be\n   confused with the user's orange bubbles. Rendered as Markdown. */\n.msg.user.harness {\n  align-self: stretch;\n  max-width: 100%;\n  white-space: normal;\n  text-align: left;\n  background: rgba(97, 175, 239, 0.12);\n  border: 1px solid rgba(97, 175, 239, 0.45);\n  color: var(--nudge-fg);\n}\n.msg.user.harness .harness-label {\n  font-size: var(--fs-xs);\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--info);\n  margin-bottom: 4px;\n}\n.msg.user.harness .harness-md {\n  min-width: 0;\n}\n.msg.user.harness .harness-md p {\n  margin: 4px 0;\n}\n.msg.user.harness .harness-md > :first-child {\n  margin-top: 0;\n}\n.msg.user.harness .harness-md > :last-child {\n  margin-bottom: 0;\n}\n.msg.user.harness .harness-md ul,\n.msg.user.harness .harness-md ol {\n  margin: 4px 0;\n  padding-left: 1.4em;\n}\n.msg.user.harness .harness-md li {\n  margin: 2px 0;\n}\n.msg.user.harness .harness-md code {\n  background: var(--sink-2);\n  border-radius: 3px;\n  padding: 0 3px;\n}\n.msg.user.harness .harness-md pre {\n  background: var(--sink-2);\n  border-radius: 5px;\n  padding: 6px 8px;\n  overflow-x: auto;\n  margin: 6px 0;\n}\n.msg.user.harness .harness-md a {\n  color: #fff;\n  text-decoration: underline;\n}\n.msg.user.harness .harness-md strong {\n  font-weight: 600;\n}\n/* \"Sent with these files\" chips inside a user bubble: the message keeps the\n   typed prompt; the attached documents are shown as a compact indicator\n   (their contents live in the LLM context, not in the transcript). */\n/* Synthetic compacted prompt: a recognizable icon before the marker. */\n.msg.user.synthetic-summary .synthetic-icon {\n  vertical-align: -2px;\n  margin-right: 5px;\n}\n/* The CHECKPOINT — the summary that OPENS the context window. It is not a\n   message the user typed, so it must not read like one: full width, framed, its\n   own VIOLET (not the terracotta of a typed prompt), and its bottom corners\n   square so the summary below it reads as the SAME card. */\n.msg.user.synthetic-summary {\n  align-self: stretch;\n  max-width: 100%;\n  white-space: normal;\n  text-align: left;\n  border-bottom-left-radius: 0;\n  border-bottom-right-radius: 0;\n  background: var(--summary-msg);\n  opacity: 0.9;\n}\n/* The summary BODY: attached under the label, with no bubble chrome of its own. It stays\n   NEUTRAL — the violet marks the header, not the text you have to read. */\n.msg.assistant.synthetic-body {\n  align-self: stretch;\n  max-width: 100%;\n  border-top-left-radius: 0;\n  border-top-right-radius: 0;\n  background: var(--overlay-1);\n  border: 1px solid var(--overlay-2);\n  border-top: none;\n}\n/* The pointer to the summary card, left where the reader actually is: after a\n   compaction the card opens the window, i.e. several screens ABOVE the bottom. */\n.compacted-hint {\n  align-self: stretch;\n  text-align: center;\n  margin: 6px 0;\n}\n.compacted-hint > button {\n  height: 18px;\n  min-height: 0;\n  padding: 0 10px;\n  display: inline-flex;\n  align-items: center;\n  background: var(--surface-2);\n  color: var(--muted);\n  border: 1px solid var(--overlay-3);\n  border-radius: 999px;\n  box-shadow: none;\n  filter: none;\n  font-size: var(--fs-xs);\n  font-weight: 600;\n  line-height: 1;\n  white-space: nowrap;\n  cursor: pointer;\n}\n.compacted-hint > button:hover {\n  color: var(--accent);\n  border-color: var(--accent);\n  background: var(--accent-surface);\n}\n/* Older checkpoints, folded into ONE dim row: their content already lives in the\n   newest summary above, so their bodies are noise in a long transcript. */\n.old-summaries {\n  align-self: stretch;\n  text-align: center;\n  margin: 2px 0;\n  color: var(--muted-3);\n  font-size: var(--fs-xs);\n  letter-spacing: 0.04em;\n}\n/* The rule that marks where the window starts. */\n.ctx-divider {\n  align-self: stretch;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin: 12px 0 4px;\n  color: var(--muted-3);\n  font-size: var(--fs-xs);\n  letter-spacing: 0.06em;\n  text-transform: uppercase;\n}\n.ctx-divider::before,\n.ctx-divider::after {\n  content: \"\";\n  flex: 1;\n  height: 1px;\n  background: currentColor;\n  opacity: 0.4;\n}\n.msg-attachments {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 8px;\n  margin-top: 6px;\n  max-width: 100%;\n}\n/* Non-image attachments: a large per-type icon + name + size. */\n.msg-attach-files {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.msg-attach-file {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 2px;\n  padding: 8px 12px;\n  border-radius: 8px;\n  min-width: 5.5rem;\n  max-width: 12rem;\n  background: rgba(0, 0, 0, 0.3);\n  border: 1px solid rgba(255, 255, 255, 0.14);\n}\n.msg-attach-file-icon {\n  line-height: 0;\n}\n.msg-attach-file-name {\n  font-size: var(--fs-sm);\n  color: #e8e8e8;\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.msg-attach-file-size {\n  font-size: var(--fs-xs);\n  color: var(--muted-2);\n}\n.msg.assistant,\n.msg.tool {\n  width: 100%;\n  max-width: 100%;\n}\n.msg.assistant {\n  align-self: flex-start;\n  background: var(--assistant-msg);\n  min-width: 0;\n  position: relative;\n  font-size: var(--fs-lg);\n}\n/* Per-turn metrics badge (REAL usage + timings) under an assistant bubble.\n   flex-shrink: 0 is REQUIRED: #messages is a flex column and this item has\n   overflow: hidden, so its automatic min-height is 0 and it would be\n   squashed to 0px (invisible) as soon as the transcript overflows. */\n.msg-meta {\n  flex-shrink: 0;\n  align-self: flex-start;\n  max-width: 92%;\n  margin: -2px 0 2px 4px;\n  font-size: var(--fs-sm);\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n  user-select: text;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n/* The mode chip leading the badge: the SAME quiet gray as the model and the\n   counts that follow it for Analyze. In BUILD only the WORD takes the accent —\n   the rest of the line stays gray, so the chip is a marker you can scan for and\n   not a loud row repeated under half the transcript. */\n.msg-meta .meta-mode {\n  padding: 0 4px;\n  border-radius: 3px;\n  background: var(--overlay-1);\n  font-size: var(--fs-sm);\n}\n/* The one orange thing on the line: the word itself. Background and the text that\n   follows keep their neutral tone. */\n.msg-meta .meta-mode.build {\n  color: var(--accent);\n}\n/* Bubble action tabs: the ⎇ branch key on assistant replies and the ✂ cut\n   key on user prompts become little \"linguette\" anchored to the bubble's\n   TOP-RIGHT. On hover they SLIDE UP out of the bubble (same fade/reveal as\n   before) so they stay clearly visible instead of blending into the text. */\n.branch-at,\n.truncate-at {\n  position: absolute;\n  top: 0;\n  right: 8px;\n  z-index: 4;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 20px;\n  min-width: 24px;\n  padding: 0 6px;\n  background: var(--surface-2);\n  border: 1px solid var(--overlay-3);\n  border-bottom: none;\n  border-radius: 6px 6px 0 0;\n  color: var(--fg-dim);\n  line-height: 1;\n  cursor: pointer;\n  opacity: 0;\n  pointer-events: none;\n  transform: translateY(6px);\n  transition:\n    opacity 0.14s ease,\n    transform 0.14s ease,\n    color 0.12s,\n    border-color 0.12s,\n    background-color 0.12s;\n}\n/* …and on an ERROR bubble the tab is made of THAT bubble, because that bubble is not made of\n   `--surface-2`: it carries a red wash and a red edge of its own. The tab INHERITS both\n   instead of restating the tint, so it cannot drift from the bubble it belongs to — and on a\n   red bubble it stops reading as a black linguetta stuck on somebody else's message.\n   That is why `--error-bg` is an OPAQUE, pre-composited value: the risen tab overlaps the\n   bubble above it, so an inherited ALPHA would let that bubble show through the tab.\n   `:where()` so the correction carries ZERO specificity — `.branch-at:hover` is one class\n   deeper than the plain selector, and a real class here would outrank it and silently kill\n   the accent repaint on hover. */\n:where(.msg.assistant.error) .branch-at {\n  background-color: inherit;\n  border-color: inherit;\n}\n/* The ✂ tab sits on an ORANGE user bubble: use the SAME orange as the\n   bubble so it reads as a tab made of the same material. */\n.truncate-at {\n  background: var(--user-msg);\n  border-color: rgba(255, 255, 255, 0.28);\n  color: #fff;\n}\n.msg.assistant:hover .branch-at,\n.msg.user:hover .truncate-at {\n  opacity: 1;\n  pointer-events: auto;\n  transform: translateY(-100%);\n}\n/* Disabled (session working): fully inert — no hover reaction, hidden. */\n.msg.assistant:hover .branch-at:disabled,\n.msg.user:hover .truncate-at:disabled {\n  opacity: 0;\n  pointer-events: none;\n}\n/* Disabled (session working): hidden even WITHOUT hover. The global\n   button:disabled opacity (0.3) outranks the base .truncate-at opacity 0,\n   which left the tab faintly visible during a run. */\n.branch-at:disabled,\n.truncate-at:disabled {\n  opacity: 0;\n  pointer-events: none;\n}\n.branch-at:hover:not(:disabled) {\n  color: var(--accent);\n  border-color: var(--accent);\n  background: var(--accent-surface);\n}\n.truncate-at:hover:not(:disabled) {\n  color: #fff;\n  border-color: #fff;\n  background: var(--accent-strong);\n}\n/* …but on the CHECKPOINT header the ✂ tab is made of the violet the header is made of:\n   a terracotta tab on a violet card would look like it belongs to another bubble. */\n.msg.user.synthetic-summary .truncate-at {\n  background: var(--summary-msg);\n}\n.msg.user.synthetic-summary .truncate-at:hover:not(:disabled) {\n  background: var(--summary-strong);\n}\n.msg.assistant.error {\n  background: var(--error-bg);\n  border: 1px solid var(--error);\n}\n.msg.assistant.loop {\n  background: rgba(245, 166, 35, 0.12);\n  border: 1px solid var(--warn);\n}\n/* Prominent \"Switch to Build\" call to action (Analyze prepared previews). */\n.build-cta {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 10px;\n  width: 100%;\n  margin: 8px 0;\n  padding: 10px 12px;\n  border: 1px solid var(--warn);\n  border-radius: 6px;\n  background: rgba(245, 166, 35, 0.16);\n}\n.build-cta-static {\n  background: rgba(245, 166, 35, 0.07);\n  border-color: rgba(245, 166, 35, 0.4);\n}\n.build-cta-static .build-cta-text {\n  color: var(--muted-2);\n}\n.build-cta-text {\n  color: var(--fg-strong);\n  font-size: 13px;\n}\n.msg.assistant p {\n  margin: 4px 0;\n}\n.msg.assistant h1,\n.msg.assistant h2,\n.msg.assistant h3,\n.msg.assistant h4,\n.msg.assistant h5,\n.msg.assistant h6 {\n  margin: 8px 0 4px;\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n.msg.assistant h1 {\n  font-size: 1.15em;\n}\n.msg.assistant h2 {\n  font-size: 1.05em;\n}\n.msg.assistant h3 {\n  font-size: 1em;\n}\n.msg.assistant ul,\n.msg.assistant ol {\n  margin: 4px 0;\n  padding-left: 1.4em;\n}\n.msg.assistant ol {\n  list-style: decimal;\n}\n.msg.assistant ul {\n  list-style: disc;\n}\n.msg.assistant li {\n  margin: 2px 0;\n}\n.msg.assistant code {\n  background: var(--tool-bg);\n  border-radius: 3px;\n  padding: 0 3px;\n  font-size: 1em;\n}\n.msg.assistant pre {\n  background: var(--tool-bg);\n  border: 1px solid var(--border);\n  border-radius: 5px;\n  padding: 6px 8px;\n  overflow-x: auto;\n  margin: 6px 0;\n}\n.msg.assistant pre code {\n  background: transparent;\n  padding: 0;\n}\n.msg.assistant a {\n  color: var(--accent);\n}\n.msg.assistant strong {\n  font-weight: 600;\n}\n.msg.assistant em {\n  font-style: italic;\n}\n.msg.assistant blockquote {\n  border-left: 2px solid var(--border);\n  padding-left: 8px;\n  margin: 6px 0;\n  color: var(--muted-2);\n}\n.msg.assistant table {\n  border-collapse: separate;\n  border-spacing: 0;\n  font-size: var(--fs-md);\n}\n.msg.assistant th,\n.msg.assistant td {\n  border: 1px solid var(--border);\n  padding: 3px 6px;\n  text-align: left;\n}\n.msg.assistant th {\n  background: var(--tool-bg);\n}\n.msg.assistant img {\n  max-width: 100%;\n  border-radius: 4px;\n}\n/* The wrapper OWNS the whole rounded frame and shrink-wraps the table\n   (fit-content): no full-width line when the table is narrower, and the\n   right corners follow the same radius. Cells only draw INTERIOR grid\n   lines (outer edges suppressed — the frame belongs to the wrapper).\n   An inline-block wrapper left this UNBOUNDED: a shrink-to-fit width resolves\n   max-width:100% against the CONTENT itself, so a wide table made the wrapper as\n   wide as the table and there was nothing left to scroll — the table was clipped\n   by the panel edge instead (visible as a missing right corner). A block with\n   width:fit-content does the same shrink-wrapping against a DEFINITE containing\n   block, and the styled scrollbar below is what makes the scroll VISIBLE: on macOS\n   overlay scrollbars are invisible until you scroll, so a working scrollable table\n   looked broken. */\n.table-scroll {\n  display: block;\n  width: fit-content;\n  max-width: 100%;\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  overflow-x: auto;\n  overflow-y: hidden;\n  margin: 6px 0;\n}\n.table-scroll::-webkit-scrollbar {\n  height: 9px;\n}\n.table-scroll::-webkit-scrollbar-track {\n  background: transparent;\n}\n.table-scroll::-webkit-scrollbar-thumb {\n  background: var(--scroll-thumb);\n  border-radius: 5px;\n}\n.table-scroll::-webkit-scrollbar-thumb:hover {\n  background: var(--scroll-thumb-hover);\n}\n.table-scroll table {\n  min-width: max-content;\n  border-collapse: separate;\n  border-spacing: 0;\n}\n.msg.assistant .table-scroll th,\n.msg.assistant .table-scroll td,\n.thinking-body .table-scroll th,\n.thinking-body .table-scroll td {\n  border: none;\n  border-right: 1px solid var(--border);\n  border-bottom: 1px solid var(--border);\n}\n/* Right column & bottom row: the line comes from the wrapper's frame. */\n.msg.assistant .table-scroll th:last-child,\n.msg.assistant .table-scroll td:last-child,\n.thinking-body .table-scroll th:last-child,\n.thinking-body .table-scroll td:last-child {\n  border-right: none;\n}\n.msg.assistant .table-scroll tr:last-child th,\n.msg.assistant .table-scroll tr:last-child td,\n.thinking-body .table-scroll tr:last-child th,\n.thinking-body .table-scroll tr:last-child td {\n  border-bottom: none;\n}\n.code-block {\n  overflow-x: auto;\n}\n.code-lang {\n  font-size: var(--fs-xs);\n  text-transform: uppercase;\n  letter-spacing: 0.4px;\n  color: var(--muted);\n  background: var(--sink-1);\n  padding: 1px 8px;\n  border-bottom: 1px solid var(--border);\n}\n/* EXPERIMENT: the tool cards take the thinking one's background — no fill of their own,\n   so the panel's own background shows through (the hairline frame stays). It used to be\n   background var(--tool-bg): #1a1a1a on the dark theme, LIGHTER than the #111111 panel. */\n.msg.tool {\n  align-self: flex-start;\n  background: transparent;\n  border: 1px solid var(--border);\n  font-size: var(--fs-md);\n}\n.msg.welcome {\n  align-self: center;\n  background: transparent;\n  border: 1px dashed var(--border);\n  color: var(--muted);\n  text-align: center;\n  max-width: 100%;\n}\n/* Brand mark inline in the greeting. The artwork is WIDE (22x16 inside the\n   square 24x24 viewBox), so the box is scaled up to ~1.4em to make the\n   visible mark match the surrounding text height. */\n.msg.welcome .welcome-logo {\n  width: 1.4em;\n  height: 1.4em;\n  vertical-align: -0.4em;\n  display: inline-block;\n}\n.working {\n  align-self: flex-start;\n  color: var(--muted-2);\n  font-size: var(--fs-md);\n  font-style: italic;\n  animation: harny-pulse 1.2s ease-in-out infinite;\n}\n/* The working bar is a REAL footer glued below the transcript (NOT a bubble\n   in the flow): always visible in realtime while it exists. It lives\n   outside #messages, so sections are never inserted below it. The text\n   pulses with the same 1.2s cadence as the play button (harny-pulse). */\n#working-bar {\n  flex-shrink: 0;\n  padding: 4px 10px;\n  background: var(--bg);\n  color: var(--muted-2);\n  font-size: var(--fs-md);\n  font-style: italic;\n  animation: harny-pulse 1.2s ease-in-out infinite;\n}\n#working-bar.hidden {\n  display: none;\n}\n/* Messages typed WHILE the session works: a real footer (outside\n   #messages) so they survive streaming re-renders. Queue = neutral, steer\n   = accent. Each is cancellable until it is applied. */\n#pending-section {\n  flex-shrink: 0;\n  background: var(--bg);\n  border-top: 1px dashed var(--border);\n}\n#pending-section.hidden {\n  display: none;\n}\n/* Same shape as the sessions header (arrow + label, whole row clickable), so\n   the two collapsible sections behave and read the same way. */\n#pending-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  padding: 5px 10px;\n  font-weight: 700;\n  font-size: var(--fs-md);\n  color: var(--fg-strong);\n  cursor: pointer;\n  user-select: none;\n}\n#pending-head:hover {\n  color: var(--accent);\n}\n#pending-head .toggle {\n  font-size: var(--fs-xs);\n}\n/* Expanded, the WHOLE list is readable and the SECTION does the scrolling: one\n   scrollbar for the group (bounded so the transcript keeps its space) instead\n   of a cap per bubble. */\n#pending-area {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  padding: 0 10px 6px;\n  max-height: 30vh;\n  overflow-y: auto;\n}\n#pending-area.hidden {\n  display: none;\n}\n.pending-msg {\n  display: flex;\n  align-items: flex-start;\n  /* The MARK sits 5px off the text beside it — the same 5px that separates the fold from the icon\n     in `.tool-header` and `.thinking-header`, so the first two marks of every row in the transcript\n     start on one rhythm. The badge→text gap keeps its 8px (see `.pending-main`), and the commands\n     are pinned right, so this gap never moves them. */\n  gap: 5px;\n  min-width: 0;\n  /* ONE THINKING ROW TALL (experiment): `.thinking-block`'s 1px dashed edge plus\n     `.thinking-header`'s 5px of padding, and the same line box (1rem x 1.4) — so a pending row\n     and a thinking row are the same height and stack as one rhythm in the transcript. */\n  padding: 5px 8px;\n  border-radius: 6px;\n  font-size: var(--fs-md);\n  border: 1px solid var(--border);\n  background: var(--surface-2);\n  color: var(--muted);\n}\n/* STEER, told apart by TONE and not by hue. Three relationships, and they are the SAME ones the\n   \"Insert prompt in\" hint uses (see #insert-hint-word), so the two places cannot drift into two\n   different ideas of what steer looks like:\n     - the bubble steps DOWN to the tool bubbles' bath (--tool-bg), and its pill steps UP\n       (--surface-2). That is what makes the steer pill \"a little lighter than the Queued one\"\n       (--tool-bg inside its --surface-2 bubble) while both stay GREY — and it is also the only\n       way the pill can be visible at all: a --surface-2 pill on a --surface-2 bubble is no pill.\n     - the EDGE steps up from --border to --overlay-3, so a steer row is lighter than a queued one\n       at the frame too, not only in the fill.\n     - the text goes to --fg (from --muted).\n   The one thing that keeps the accent is the MARK (see .pending-msg.pending-steer .pending-mark). */\n.pending-msg.pending-steer {\n  background: var(--tool-bg);\n  border-color: var(--overlay-3);\n  color: var(--fg);\n}\n.pending-badge {\n  flex: 0 0 auto;\n  font-size: var(--fs-sm);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  /* ONE text line tall: the ROW's line-height x its font-size, the same box the\n     text next to it occupies. The badge used to inherit the default line-height,\n     so it came out 2.38px shorter than that line and — the row aligns children to\n     the top (align-items: flex-start) — all of the 3px padding ended up BELOW it\n     (measured: 3 above, 5.38 below, on both the Steer pill and the Queued one).\n     Matching the box makes the two gaps equal WITHOUT centring the label in a\n     bubble that can grow to several lines. */\n  line-height: calc(var(--fs-md) * 1.4);\n  /* ONE WIDTH FOR BOTH LABELS — and the width is MEASURED, not guessed: the badge is a ONE-CELL\n     grid, and a hidden copy of the longer label (\"Queued\") shares that cell with the visible one\n     (see .pending-badge-sizer). Both pills are therefore exactly the same box in any font, at any\n     zoom, with no number to keep in sync, and converting a message cannot resize the badge (the\n     text never shifts under the pointer). */\n  display: inline-grid;\n  justify-items: center;\n  align-items: center;\n  padding: 0 5px;\n  border-radius: 999px;\n  background: var(--tool-bg);\n  color: var(--muted);\n}\n.pending-msg.pending-steer .pending-badge {\n  background: var(--surface-2);\n  color: var(--fg);\n}\n/* The mark of the MODE (steer cuts the line, queue waits at its end), in the place a tool call\n   wears its own: it LEADS the row, before the pill it makes redundant on purpose. `inline-flex` +\n   one text line of height so the drawing sits on the first line's centre even when the text runs\n   to four — and so the shared 1.25 transform (see the \"in testa\" rule) can apply at all, since a\n   transform does nothing on a non-replaced inline box. Muted by default; a steer row is the\n   accent one. */\n.pending-mark {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  min-height: 1.4em;\n  color: var(--muted-2);\n}\n.pending-msg.pending-steer .pending-mark {\n  color: var(--accent);\n}\n/* The pill's RULER: it carries the longer label and no ink (invisible, `aria-hidden` in the\n   markup), so it sets the width without ever being read out or selected. */\n.pending-badge-sizer {\n  visibility: hidden;\n}\n/* ONE CELL, two occupants: the label is drawn, the sizer only measures. `grid-area: 1 / 1` on both\n   is what keeps them stacked — without it the ghost would sit BESIDE the label and double the pill. */\n.pending-badge-sizer,\n.pending-badge-label {\n  grid-area: 1 / 1;\n}\n/* The row is badge + content + actions: the text and its attachments share the\n   middle column (so the previews land UNDER the text, as in a user bubble) while\n   the commands stay pinned to the top-right corner. */\n.pending-main {\n  flex: 1;\n  min-width: 0;\n  /* The row's gap is the mark's 5px (see `.pending-msg`); the badge keeps its own 8px of air from\n     the text it labels. */\n  margin-left: 3px;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n/* The text is ALWAYS WHOLE: it wraps, keeps the user's own line breaks, and the row grows as tall\n   as it needs while the SECTION owns the scroll (#pending-area). There is no clamp and no fold any\n   more — see the module comment in pending-section.ts for why the per-row fold was removed. */\n.pending-text {\n  flex: 1;\n  min-width: 0;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  line-height: 1.4;\n}\n/* The SHARED attachment row (the one user bubbles render), inside a pending row:\n   identical content, a hair tighter — the main column already spaces it. */\n.pending-extras .msg-attachments {\n  margin-top: 0;\n  gap: 6px;\n}\n/* The buttons sit TOP-RIGHT, pinned with margin-left: auto so multi-line text never moves them. */\n.pending-actions {\n  flex: 0 0 auto;\n  margin-left: auto;\n  display: flex;\n  gap: 4px;\n}\n/* The pill chrome belongs to the two commands, and only to them: there is no bare chevron in this\n   row any more, so no `:not()` guard is needed to keep one from wearing it. */\n.pending-actions button {\n  flex: 0 0 auto;\n  min-height: 1.2rem;\n  padding: 0 0.4rem;\n  background: transparent;\n  border: 1px solid var(--border);\n  color: var(--muted);\n  box-shadow: none;\n  font-size: var(--fs-sm);\n  white-space: nowrap;\n}\n.pending-actions button:hover {\n  filter: none;\n}\n.pending-cancel:hover {\n  color: var(--error);\n  border-color: var(--error);\n}\n.pending-convert:hover {\n  color: var(--accent);\n  border-color: var(--accent);\n}\n/* A steer that became a real user turn: a thin accent bar on the left. */\n.msg.user.steer-msg {\n  border-left: 2px solid var(--accent);\n}\n@keyframes harny-pulse {\n  0%,\n  100% {\n    opacity: 1;\n  }\n  50% {\n    opacity: 0.35;\n  }\n}\n/* The ACTIVE areas pulse their border with the SAME 1.2s ease-in-out\n   cadence as the play button (harny-pulse) and IN PHASE with it: the\n   peak (full accent + glow) is at 0%/100% of the cycle, exactly when the\n   play key is at full opacity; 50% is the dim beat, matching the play\n   key's fade. Deliberately evident: 2px border breathing between a soft\n   accent edge and the full accent with a visible glow. Applied to the\n   answer bubble being filled AND the live thinking block while it works.\n   box-sizing:border-box keeps the border inside (no layout jump). */\n@keyframes stream-border-pulse {\n  0%,\n  100% {\n    border-color: var(--accent);\n    box-shadow: 0 0 14px 1px var(--accent-glow);\n  }\n  50% {\n    border-color: var(--accent-line);\n    box-shadow: 0 0 4px 0 var(--accent-glow-soft);\n  }\n}\n/* Same cadence/phase as stream-border-pulse, but in the SUB-AGENT violet so\n   a running sub-agent glows with a halo close to its own border color. */\n@keyframes stream-border-pulse-violet {\n  0%,\n  100% {\n    border-color: var(--violet);\n    box-shadow: 0 0 14px 1px rgba(124, 92, 255, 0.5);\n  }\n  50% {\n    border-color: rgba(124, 92, 255, 0.4);\n    box-shadow: 0 0 4px 0 rgba(124, 92, 255, 0.15);\n  }\n}\n.msg.assistant.streaming {\n  border: 2px solid var(--accent-line);\n  animation: stream-border-pulse 1.2s ease-in-out infinite;\n}\n/* Live thinking header (the block is collapsed by default, so this is the\n   visible \"working\" indicator): same cadence, accent edges. */\n.thinking-block.streaming {\n  animation: stream-border-pulse 1.2s ease-in-out infinite;\n}\n/* Graceful end: when a stream finishes the pulse settles out smoothly\n   (~0.7s fade) instead of snapping off — the answer bubble fades back to\n   borderless, the thinking block back to its quiet dashed edge. */\n.msg.assistant.settling {\n  border: 2px solid var(--accent-line);\n  animation: none;\n  transition:\n    border-color 0.7s ease,\n    box-shadow 0.7s ease;\n  border-color: transparent;\n  box-shadow: none;\n}\n.thinking-block.settling {\n  animation: none;\n  transition: border-color 0.7s ease;\n  border-color: var(--border);\n}\n\n.tool-header {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  cursor: pointer;\n  user-select: none;\n  font-weight: 600;\n  color: var(--accent);\n  min-width: 0;\n}\n.tool-header:hover {\n  color: var(--fg);\n}\n.tool-toggle {\n  font-size: var(--fs-sm);\n}\n/* Tool call header: the tool's own mark, then its name. inline-flex keeps the\n   icon on the text's baseline whatever the font-size does. */\n.tool-name {\n  white-space: nowrap;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n}\n.tool-name > svg {\n  flex: 0 0 auto;\n}\n/* A call whose NAME FIELD carried the arguments (`Greplike\" string=\"true` — real transcript,\n   see core/tools/unknown-tool.ts): it never was a tool, so it must not be painted like one.\n   Monospace and the error colour say \"this is text the model got wrong\", and the question\n   badge it wears is not a missing icon. */\n.msg.tool[data-tool-invalid=\"1\"] .tool-name,\n.sa-tool[data-tool-invalid=\"1\"] {\n  color: var(--error);\n  font-family: var(--font-mono);\n}\n/* \"In testa\" marks of a bubble — the tool, thinking, sub-agent and synthetic-summary icons —\n   are painted a QUARTER larger (1.25×). A TRANSFORM, never a bigger width/height: a transform\n   does not enter the layout, so no bubble, row or gap changes size (the icon's box stays 13px;\n   only its ink grows). Centred origin keeps the growth inside the header's own 5px gap.\n   1.5× was tried and read as too big; this is the middle ground — ONE number, tune it here. */\n.tool-name > svg,\n.thinking-header > svg,\n.subagent-header .subagent-icon,\n.msg.user.synthetic-summary .synthetic-icon,\n.pending-msg .pending-mark {\n  transform: scale(1.25);\n  transform-origin: center;\n}\n/* Target file path shown after the tool name (light azure, ellipsized,\n   truncated softly when the bubble is narrow — full path on hover). */\n.tool-path {\n  color: var(--info);\n  font-weight: 400;\n  flex: 0 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  opacity: 0.95;\n}\n.tool-details {\n  margin-top: 2px;\n  font-size: var(--fs-md);\n}\n.tool-details.collapsed {\n  display: none;\n}\n/* TodoWrite: a task LIST, not a log line. Inside the collapsed .tool-details the\n   list was invisible in practice (one closed bubble per update, and the tool is\n   called once per change), so it gets its own block under the header — visible\n   without expanding. There is only ever ONE in the transcript: the newest state. */\n.todo-block {\n  margin: 3px 0 1px;\n  padding-left: 8px;\n  border-left: 2px solid var(--border);\n}\n.todo-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n.todo-count {\n  color: var(--fg-strong);\n  font-weight: 700;\n}\n.todo-list {\n  list-style: none;\n  margin: 4px 0 0;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n.todo-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 6px;\n  min-width: 0;\n  font-size: var(--fs-md);\n  color: var(--fg);\n}\n/* The checkbox: a BOX, not a glyph — 12px, square-ish, with the tick drawn by an icon in the\n   panel's own ink. It is a span (aria-hidden): the tasks belong to the model, so a real input\n   would promise a toggle nobody can make. */\n.todo-check {\n  flex: none;\n  width: 12px;\n  height: 12px;\n  margin-top: 1px;\n  border: 1px solid var(--muted-2);\n  border-radius: 3px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--bg);\n}\n.todo-item.status-completed .todo-check {\n  background: var(--ok);\n  border-color: var(--ok);\n}\n/* In progress: a filled dot inside an accent box — \"being done\", between empty and ticked. */\n.todo-item.status-in_progress .todo-check {\n  border-color: var(--accent);\n}\n.todo-item.status-in_progress .todo-check::after {\n  content: \"\";\n  width: 4px;\n  height: 4px;\n  border-radius: 50%;\n  background: var(--accent);\n}\n.todo-item.status-cancelled .todo-check {\n  border-color: var(--muted);\n  color: var(--muted);\n}\n.todo-text {\n  min-width: 0;\n  overflow-wrap: anywhere;\n}\n/* DONE reads as DONE, not as deleted: the green box at the start and BOLD text — no strikethrough\n   (a line through the words is the universal sign of \"gone\") and no dimming, because a finished\n   task is an accomplishment, not a footnote. */\n.todo-item.status-completed .todo-text {\n  font-weight: 600;\n  color: var(--fg-strong);\n}\n.todo-item.status-cancelled {\n  color: var(--muted);\n}\n.todo-item.status-cancelled .todo-text {\n  text-decoration: line-through;\n}\n.tool-label {\n  display: block;\n  color: var(--muted);\n  font-size: var(--fs-xs);\n  text-transform: uppercase;\n  letter-spacing: 0.4px;\n  margin: 6px 0 2px;\n}\n.tool-details pre {\n  background: var(--sink-1);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 5px 7px;\n  white-space: pre-wrap;\n  word-break: break-all;\n  max-height: 160px;\n  overflow-y: auto;\n  font-size: var(--fs-md);\n  line-height: 1.4;\n}\n/* The Task/Input arguments block is a <pre>: WRAP it at the bubble width\n   (the sub-agent \"Task\" lives OUTSIDE .tool-details, so it needs its own\n   rule) and GROW vertically with the wrapped content — no max-height /\n   scrollbar (the bubble simply gets taller). */\n.tool-args {\n  background: var(--sink-1);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 5px 7px;\n  margin: 0;\n  white-space: pre-wrap;\n  word-break: break-all;\n  font-family: var(--font-mono);\n  font-size: var(--fs-md);\n  line-height: 1.4;\n}\n.tool-result-error {\n  color: var(--error);\n}\n/* Diff section INSIDE the tool bubble (third section: Input / Output /\n   Diff). Replaces the previous separate .msg.file-diff bubble: the diff\n   lives in the collapsed .tool-details together with Input and Output, so\n   it expands with the tool bubble — no flex-shrink hazard, no 2px strip. */\n.tool-diff {\n  margin-top: 2px;\n}\n.tool-diff-head {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n}\n.tool-diff-head .tool-label {\n  margin: 6px 0 2px;\n}\n.fd-stat {\n  opacity: 0.7;\n  font-weight: 500;\n  font-size: var(--fs-xs);\n}\n.fd-body {\n  padding: 0 0 4px;\n  font-size: var(--fs-md);\n  line-height: 1.5;\n}\n.fd-body div {\n  padding: 0 10px;\n  white-space: pre-wrap;\n  word-break: break-all;\n}\n.fd-add {\n  color: var(--ok);\n  background: var(--ok-bg);\n}\n.fd-del {\n  color: var(--del);\n  background: var(--del-bg);\n}\n.fd-hunk {\n  color: var(--accent);\n  background: var(--overlay-1);\n}\n.fd-ctx {\n  color: inherit;\n  opacity: 0.8;\n}\n/* Editor-style syntax tokens inside the diff lines (Prism classes). One-dark\n   and one-light are the two readings of the SAME roles, so a light theme gets\n   readable code instead of a washed-out one: see the code-* roles in\n   view-config.ts. */\n.fd-body .token {\n  color: inherit;\n  opacity: 1;\n}\n.fd-body .token.comment,\n.fd-body .token.prolog,\n.fd-body .token.cdata {\n  color: var(--code-comment);\n  font-style: italic;\n}\n.fd-body .token.keyword,\n.fd-body .token.selector,\n.fd-body .token.atrule,\n.fd-body .token.important {\n  color: var(--code-keyword);\n}\n.fd-body .token.string,\n.fd-body .token.attr-value,\n.fd-body .token.char,\n.fd-body .token.regex {\n  color: var(--code-string);\n}\n.fd-body .token.number,\n.fd-body .token.boolean,\n.fd-body .token.constant {\n  color: var(--code-number);\n}\n.fd-body .token.function,\n.fd-body .token.function-variable {\n  color: var(--code-function);\n}\n.fd-body .token.class-name,\n.fd-body .token.maybe-class-name {\n  color: var(--code-class);\n}\n.fd-body .token.builtin {\n  color: var(--code-builtin);\n}\n.fd-body .token.operator,\n.fd-body .token.punctuation {\n  color: var(--code-operator);\n}\n.fd-body .token.property,\n.fd-body .token.attr-name,\n.fd-body .token.variable {\n  color: var(--code-property);\n}\n.fd-body .token.doctype,\n.fd-body .token.entity {\n  color: var(--code-property);\n}\n.tool-call-pending {\n  opacity: 0.65;\n}\n\n/* Sub-agent (Delegate) bubble: clearly shows that the orchestrator LAUNCHED\n   a sub-agent — id/role, live status, the goal in clear text and the\n   declared resources/access it may touch. Tinted violet to stand out from\n   ordinary tool calls. */\n.msg.tool.subagent {\n  border-color: rgba(124, 92, 255, 0.45);\n  background: rgba(124, 92, 255, 0.06);\n}\n/* While THIS sub-agent runs, its bubble pulses with the SAME cadence/phase\n   as the thinking/answer bubbles but in its OWN violet (halo matching the\n   border), phase-locked to the shared clock (phaseLockPulse) so every\n   working area beats together. */\n.msg.tool.subagent.subagent-running {\n  animation: stream-border-pulse-violet 1.2s ease-in-out infinite;\n}\n/* Graceful end: settle back to the resting violet edge (~0.7s fade). */\n.msg.tool.subagent.subagent-settling {\n  animation: none;\n  transition:\n    border-color 0.7s ease,\n    box-shadow 0.7s ease;\n  border-color: rgba(124, 92, 255, 0.45);\n  box-shadow: none;\n}\n.subagent-header {\n  gap: 6px;\n  --sa-chip-h: 1.3rem;\n}\n.subagent-header .subagent-icon {\n  color: var(--violet-text);\n  vertical-align: -2px;\n}\n#working-bar .subagent-icon {\n  vertical-align: -2px;\n}\n/* In this header exactly ONE element gives way: the goal. Everything else —\n   the name, the role, the status chip, abort and the arrow — is fixed, so a\n   narrow panel cannot squeeze THEM and leave the goal at full length. */\n.subagent-header .tool-name {\n  flex: 0 0 auto;\n}\n.subagent-role {\n  color: var(--violet-text);\n  font-weight: 500;\n  flex: 0 0 auto;\n}\n/* The sub-agent's short goal in the header: what it actually does.\n   NO lower bound (min-width: 0): it may shrink all the way to nothing, and\n   the ellipsis travels left with it, because how much fits is a question\n   about the PANEL, not about the text (no character cut is applied in JS). */\n.subagent-name {\n  color: var(--muted-2);\n  font-weight: 400;\n  flex: 0 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* PINNED RIGHT (experiment): the status chip and the abort button are this row's FIXED marks, so\n   they own the right edge and the goal — the one element allowed to give way — absorbs the slack.\n   The chip used to ride right after the goal and slide left with it, which put \"RUNNING…\" and\n   \"DONE\" at a different x on every row of a fan-out: a column of states that could not be read\n   down. */\n.subagent-status {\n  margin-left: auto;\n  flex-shrink: 0;\n  display: inline-flex;\n  align-items: center;\n  height: var(--sa-chip-h);\n  box-sizing: border-box;\n  font-size: var(--fs-xs);\n  font-weight: 700;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  padding: 0 7px;\n  border-radius: 999px;\n  border: 1px solid var(--border);\n  color: var(--muted-2);\n}\n.subagent-status.queued {\n  color: var(--muted-2);\n  border-color: var(--border);\n}\n/* The \"running…\" chip is STATIC: the bubble itself carries the pulsing\n   border while this sub-agent works (see .subagent-running above). */\n.subagent-status.running {\n  color: var(--violet-text);\n  border-color: rgba(124, 92, 255, 0.5);\n}\n.subagent-status.done {\n  color: var(--ok);\n  border-color: rgba(152, 195, 121, 0.5);\n}\n.subagent-status.failed {\n  color: var(--error);\n  border-color: rgba(244, 71, 71, 0.5);\n}\n.subagent-status.aborted {\n  color: var(--muted-2);\n  border-color: var(--border);\n}\n/* Per-sub-agent abort: stop ONLY this sub-agent, not the whole run. SQUARE\n   and exactly as tall as the \"running\" chip's border box (shared\n   --sa-chip-h); the global button min-height would otherwise stretch it\n   into a rectangle. */\n.subagent-abort {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: var(--sa-chip-h);\n  height: var(--sa-chip-h);\n  min-width: var(--sa-chip-h);\n  min-height: var(--sa-chip-h);\n  padding: 0;\n  cursor: pointer;\n  color: var(--violet-text);\n  background: transparent;\n  border: 1px solid rgba(124, 92, 255, 0.45);\n  border-radius: 4px;\n  transition:\n    background-color 0.12s,\n    color 0.12s;\n}\n.subagent-abort:hover:not(:disabled) {\n  background: rgba(124, 92, 255, 0.18);\n  color: #fff;\n}\n.subagent-abort:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n.subagent-abort[hidden] {\n  display: none;\n}\n.subagent-goal {\n  padding: 0 8px 4px 22px;\n  color: var(--fg);\n  font-style: italic;\n  font-size: var(--fs-md);\n  overflow-wrap: anywhere;\n  word-break: break-word;\n}\n/* The bubble body (goal + nested stream + report) is collapsed by default. */\n.subagent-body.collapsed {\n  display: none;\n}\n/* Nested live stream inside a running sub-agent bubble. */\n.sa-log {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding: 2px 8px 6px 22px;\n  border-left: 2px solid rgba(124, 92, 255, 0.25);\n  margin: 0 0 2px 8px;\n}\n.sa-thinking {\n  color: var(--muted);\n  font-style: italic;\n  font-size: var(--fs-sm);\n  word-break: break-word;\n}\n.sa-answer {\n  color: var(--fg);\n  font-size: var(--fs-md);\n  word-break: break-word;\n}\n/* Markdown inside the nested live stream (same shapes as the thinking body). */\n/* Markdown shapes shared by the nested stream AND the sub-agent report. */\n.subagent-report {\n  color: var(--fg);\n  font-size: var(--fs-md);\n  word-break: break-word;\n}\n.sa-thinking p,\n.sa-answer p,\n.subagent-report p {\n  margin: 2px 0;\n}\n.sa-thinking ul,\n.sa-thinking ol,\n.sa-answer ul,\n.sa-answer ol,\n.subagent-report ul,\n.subagent-report ol {\n  margin: 2px 0;\n  padding-left: 1.2em;\n}\n.sa-thinking ol,\n.sa-answer ol,\n.subagent-report ol {\n  list-style: decimal;\n}\n.sa-thinking ul,\n.sa-answer ul,\n.subagent-report ul {\n  list-style: disc;\n}\n.sa-thinking li,\n.sa-answer li,\n.subagent-report li {\n  margin: 1px 0;\n}\n.sa-thinking strong,\n.sa-answer strong,\n.subagent-report strong {\n  font-weight: 600;\n}\n.sa-thinking em,\n.sa-answer em,\n.subagent-report em {\n  font-style: italic;\n}\n.sa-thinking code,\n.sa-answer code,\n.subagent-report code {\n  background: var(--sink-1);\n  border-radius: 3px;\n  padding: 0 3px;\n  font-family: var(--font-mono);\n  font-size: var(--fs-sm);\n}\n.sa-thinking pre,\n.sa-answer pre,\n.subagent-report pre {\n  background: var(--sink-1);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 4px 6px;\n  overflow-x: auto;\n  margin: 3px 0;\n  font-family: var(--font-mono);\n  font-size: var(--fs-sm);\n}\n.sa-thinking pre code,\n.sa-answer pre code,\n.subagent-report pre code {\n  background: transparent;\n  padding: 0;\n}\n.sa-thinking a,\n.sa-answer a,\n.subagent-report a {\n  color: var(--accent);\n}\n.subagent-report.tool-result-error {\n  color: var(--error);\n}\n/* Icons inlined in a TEXT line (the working bar, the sub-agent tool log)\n   need to sit on the baseline: they are flex-less inline boxes here. */\n#working-bar svg,\n.sa-tool svg {\n  vertical-align: -2px;\n  margin-right: 4px;\n}\n\n.sa-tool {\n  color: var(--muted-2);\n  font-size: var(--fs-sm);\n  font-family: var(--font-mono);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.sa-tool.pending {\n  opacity: 0.6;\n}\n.sa-tool.ok {\n  color: var(--ok);\n}\n.sa-tool.err {\n  color: var(--error);\n}\n.subagent-meta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px;\n  margin: 4px 0 2px;\n}\n.subagent-chip {\n  display: inline-flex;\n  align-items: center;\n  padding: 0 6px;\n  border-radius: 999px;\n  max-width: 100%;\n  overflow-wrap: anywhere;\n  background: var(--tool-bg);\n  border: 1px solid var(--border);\n  color: var(--muted-2);\n  font-size: var(--fs-xs);\n}\n/* The access chip's class is the RAW access the model asked for (read / write / create) while the\n   label it carries is the MODE that access maps to (Analyze / Build): the same two tones the chat's\n   mode button uses — blue for analyze, amber for build — and `write` and `create` share one rule\n   because they ARE one mode. */\n.subagent-chip.access-read {\n  color: var(--info);\n  border-color: rgba(97, 175, 239, 0.4);\n}\n.subagent-chip.access-write,\n.subagent-chip.access-create {\n  color: var(--warn-soft);\n  border-color: rgba(229, 192, 123, 0.4);\n}\n.subagent-chip.parallel {\n  color: var(--violet-text);\n  border-color: rgba(124, 92, 255, 0.4);\n}\n\n.thinking-block {\n  width: 100%;\n  border: 1px dashed var(--border);\n  border-radius: 6px;\n  margin: 4px 0;\n  padding: 0;\n  font-size: var(--fs-md);\n}\n.thinking-header {\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  padding: 5px 8px;\n  cursor: pointer;\n  user-select: none;\n  color: var(--muted-2);\n  font-style: italic;\n}\n.thinking-header:hover {\n  color: var(--accent);\n}\n.thinking-header > svg {\n  flex: 0 0 auto;\n}\n.thinking-header .toggle {\n  font-size: var(--fs-sm);\n}\n/* Thinking is now rendered as Markdown (md on the reasoning text), so the\n   body uses normal whitespace + breaks:true like the assistant bubbles. */\n.thinking-body {\n  padding: 0 8px 6px;\n  color: var(--muted-2);\n  line-height: 1.45;\n}\n.thinking-body p {\n  margin: 4px 0;\n}\n.thinking-body h1,\n.thinking-body h2,\n.thinking-body h3,\n.thinking-body h4,\n.thinking-body h5,\n.thinking-body h6 {\n  margin: 8px 0 4px;\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n.thinking-body ul,\n.thinking-body ol {\n  margin: 4px 0;\n  padding-left: 1.4em;\n}\n.thinking-body ol {\n  list-style: decimal;\n}\n.thinking-body ul {\n  list-style: disc;\n}\n.thinking-body li {\n  margin: 2px 0;\n}\n.thinking-body a {\n  color: var(--accent);\n}\n.thinking-body strong {\n  font-weight: 600;\n}\n.thinking-body em {\n  font-style: italic;\n}\n.thinking-body code {\n  background: var(--sink-1);\n  border-radius: 3px;\n  padding: 0 3px;\n  font-size: var(--fs-md);\n}\n.thinking-body pre {\n  background: var(--sink-1);\n  border: 1px solid var(--border);\n  border-radius: 4px;\n  padding: 4px 6px;\n  overflow-x: auto;\n  margin: 4px 0;\n}\n.thinking-body pre code {\n  background: transparent;\n  padding: 0;\n}\n.thinking-body blockquote {\n  border-left: 2px solid var(--border);\n  padding-left: 8px;\n  margin: 4px 0;\n}\n.thinking-body table {\n  border-collapse: separate;\n  border-spacing: 0;\n}\n.thinking-body th,\n.thinking-body td {\n  border: 1px solid var(--border);\n  padding: 3px 6px;\n  text-align: left;\n}\n.thinking-body th {\n  background: var(--sink-1);\n}\n.thinking-body img {\n  max-width: 100%;\n  border-radius: 4px;\n}\n.thinking-body hr {\n  border: none;\n  border-top: 1px solid var(--border);\n  margin: 6px 0;\n}\n.thinking-body.collapsed {\n  display: none;\n}\n\n/* Input area: a full-width card matching the sessions/control cards. */\n#input-area {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  /* Never squeezed: the prompt box (and the AI Model row with it) is part of\n     the fixed chrome — when the panel is short it is the cards below that\n     scroll, not the textarea that flattens. */\n  flex-shrink: 0;\n  margin: 8px 10px 0;\n  border-radius: 8px;\n  padding: 8px 10px 6px;\n  background: var(--input-bg);\n}\n/* Input row: the \"+\" file picker is the head key (same size as the\n   Play/Stop keys on the right), then the prompt, then ▶/⏹. */\n#input-main {\n  display: flex;\n  gap: 8px;\n  align-items: flex-end;\n  min-width: 0;\n}\n#user-input {\n  flex: 1;\n  background: var(--surface-2);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 6px 8px;\n  font-size: var(--fs-lg);\n  line-height: 1.4;\n  resize: none;\n  min-height: 2.31rem;\n  max-height: 18.5rem;\n  outline: none;\n}\n#user-input:focus {\n  border-color: var(--accent);\n}\nbutton {\n  background: var(--accent);\n  color: #fff;\n  border: none;\n  border-radius: 6px;\n  cursor: pointer;\n  font-size: var(--fs-lg);\n  line-height: 1;\n  /* All button glyphs (▶ ⏹ ✎ 🗑 − + ＋ Compact) stay centered at any font\n     size: flex centering + a font-proportional minimum hit area. */\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 1.54rem;\n  padding: 0 0.46rem;\n  /* Subtle 3D \"key\" chrome: beveled top highlight + bottom shade + small\n     drop shadow; pressing dips the key down and flattens it. */\n  box-shadow:\n    inset 0 1px 0 rgba(255, 255, 255, 0.22),\n    inset 0 -1px 0 rgba(0, 0, 0, 0.22),\n    0 1px 2px var(--key-shadow);\n  transition:\n    transform 0.08s,\n    box-shadow 0.12s,\n    filter 0.12s,\n    color 0.12s;\n}\nbutton:not(:disabled):hover {\n  filter: brightness(1.12);\n}\nbutton:not(:disabled):active {\n  transform: translateY(1px);\n  box-shadow: inset 0 1px 3px var(--key-shadow);\n}\nbutton:disabled {\n  opacity: 0.3;\n  cursor: default;\n}\n/* Icon buttons: SVG glyphs are block-level inside the flex, so the\n   baseline gap of inline svg never shifts the shape off-center. */\nbutton svg {\n  display: block;\n}\nbutton.secondary {\n  background: transparent;\n  border: 1px solid var(--border);\n  color: var(--fg);\n}\n/* Stop (abort) is ENABLED only while working: a red hover signals the\n   danger action in exactly that state (disabled elsewhere). */\n#abort-btn:enabled:hover {\n  color: var(--error);\n  border-color: var(--error);\n  background: rgba(244, 71, 71, 0.12);\n}\n/* Play/Stop keys: CSS-drawn shapes (::before) replace the ▶/⏹ font glyphs,\n   whose metric box varies per font and drifts off-center at larger sizes.\n   rem units = scale with the UI font; triangle and square have ≈ equal\n   visual mass, so the two keys look identical and centered at ANY size.\n   font-size:0 keeps the text glyph as an invisible DOM fallback. */\n#input-main button {\n  height: 2.31rem;\n  min-width: 2.77rem;\n  padding: 0 0.77rem;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n}\n\n/* Chips row under the input: queued files only — the paperclip picker lives\n   at the head of the text box (first key in #input-main). An empty row must\n   not leave a phantom gap at the bottom of the ask box: hide it entirely. */\n#attach-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n#attach-row:has(#attachment-chips.hidden) {\n  display: none;\n}\n#attach-btn {\n  color: var(--muted);\n  font-size: var(--fs-lg);\n}\n#attach-btn:not(:disabled):hover {\n  color: var(--accent);\n  border-color: var(--accent);\n  filter: none;\n}\n#attachment-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  min-width: 0;\n}\n#attachment-chips.hidden {\n  display: none;\n}\n.attach-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  max-width: 100%;\n  padding: 1px 3px 1px 8px;\n  border-radius: 999px;\n  background: var(--tool-bg);\n  border: 1px solid var(--border);\n  font-size: var(--fs-sm);\n  color: var(--fg);\n}\n.attach-name {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  max-width: 12rem;\n}\n/* An attachment that came back from a reload WITHOUT its payload: the chip keeps its\n   place (name, size) but says so, and send() refuses it instead of sending an empty\n   file. Amber, not red: it is recoverable (re-attach the file). */\n.attach-chip.attach-stale {\n  border-color: var(--warn, #d19a11);\n}\n.attach-warn {\n  color: var(--warn, #d19a11);\n}\n.attach-icon {\n  display: inline-flex;\n  align-items: center;\n  line-height: 0;\n  flex: 0 0 auto;\n}\n/* Thumbnail preview of a pasted clipboard image in its attachment chip. */\n.attach-thumb {\n  width: 22px;\n  height: 22px;\n  object-fit: cover;\n  border-radius: 3px;\n  border: 1px solid var(--border);\n  cursor: zoom-in;\n}\n/* Attached IMAGE: half the chat width by default, NEVER deformed (height\n   follows the image), resizable via the bottom-right handle. */\n.msg-attach-img {\n  display: block;\n  max-width: 100%;\n  min-width: 4rem;\n  resize: horizontal;\n  overflow: hidden;\n  border-radius: 6px;\n  border: 1px solid var(--border);\n  background: rgba(0, 0, 0, 0.25);\n}\n.msg-attach-img img {\n  display: block;\n  width: 100%;\n  height: auto;\n  cursor: zoom-in;\n}\n.msg-attach-img .msg-attach-cap {\n  /* LEFT, like the image above it: the bubble centres its TEXT, and that must not\n     leak into a caption sitting under a left-aligned preview. */\n  text-align: left;\n  font-size: var(--fs-sm);\n  color: #d0d0d0;\n  padding: 2px 6px;\n  line-height: 1.3;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* Full-size image lightbox: click a thumbnail to view it large. */\n.img-lightbox {\n  position: fixed;\n  inset: 0;\n  z-index: 1000;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n  background: rgba(0, 0, 0, 0.82);\n  cursor: zoom-out;\n}\n.img-lightbox.hidden {\n  display: none;\n}\n.img-lightbox-img {\n  max-width: 92vw;\n  max-height: 92vh;\n  object-fit: contain;\n  border-radius: 6px;\n  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.6);\n}\n/* Drag & drop affordance. */\nbody.drag-over {\n  outline: 2px dashed var(--accent);\n  outline-offset: -6px;\n}\n.attach-size {\n  color: var(--muted);\n}\n#input-area .attach-remove {\n  height: 1.15rem;\n  min-height: 0;\n  min-width: 1.15rem;\n  padding: 0;\n  background: transparent;\n  color: var(--muted);\n  border: none;\n  box-shadow: none;\n  font-size: var(--fs-lg);\n  line-height: 1;\n}\n#input-area .attach-remove:not(:disabled):hover {\n  color: var(--error);\n  filter: none;\n}\n\n/* Control-stack toggle (above the ask card): a centered chevron that is\n   ALWAYS visible (orange accent) — clicking collapses/expands the Window\n   + Sampling cards below (the rest of the controls stays visible). The\n   stack is COLLAPSED by default.\n   position:relative because this strip also HOSTS #collapse-all (right) and the\n   insert-in hint (left): the strip\n   sits outside #messages, which is the one scrolling element, so a tab\n   anchored here stays put while the transcript scrolls. */\n#ctl-toggle {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n  height: 18px;\n  margin: 8px 10px 0;\n  cursor: pointer;\n  user-select: none;\n}\n/* Transcript action pills (\"Collapse all\", \"Follow\"), right-aligned\n   inside this strip. Flat pills, deliberately WITHOUT the 3D key chrome that\n   the global button rule applies (accent fill, inset bevel, drop shadow), so\n   they read as labels rather than actions.\n   Right-aligned on purpose: the strip's center already belongs to the\n   chevron and to #working-bar.\n   They NEVER appear or disappear — only their disabled state changes — so\n   the row can never reflow under the cursor. Disabled means \"not applicable\n   right now\", not \"broken\": the pill stays put and the global\n   button:disabled rule dims it to 0.3.\n   Note: an unfilled pill would sink into the seam, which is --bg exactly like\n   the transcript; --surface-2 is what makes them read. */\n#transcript-actions {\n  position: absolute;\n  right: 0;\n  top: 0;\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n#transcript-actions > button {\n  height: 18px;\n  min-height: 0;\n  padding: 0 10px;\n  display: inline-flex;\n  align-items: center;\n  background: var(--surface-2);\n  color: var(--muted);\n  border: 1px solid var(--overlay-3);\n  border-radius: 999px;\n  box-shadow: none;\n  filter: none;\n  font-size: var(--fs-xs);\n  font-weight: 600;\n  line-height: 1;\n  white-space: nowrap;\n}\n#transcript-actions > button:disabled {\n  cursor: default;\n}\n#transcript-actions > button:not(:disabled):hover {\n  color: var(--accent);\n  border-color: var(--accent);\n  background: var(--accent-surface);\n  /* Kill the global button hover glow too: the pill must stay flat. */\n  filter: none;\n}\n/* No dip, no bevel: the pill does not move when clicked. */\n#transcript-actions > button:not(:disabled):active {\n  transform: none;\n  box-shadow: none;\n}\n/* Insert-in hint: the LEFT slot of this same strip, mirroring #transcript-actions on\n   the right. It replaces the old Queue/Steer pill that lived in the model row:\n   \"Insert prompt in Queue\" / \"Insert prompt in Steer\". A pure INDICATOR — never clickable — so it\n   is a plain span: no button chrome, no focus ring. Both states keep the word in a\n   pill of the strip's own height, so the row cannot reflow when the word changes. */\n#insert-hint {\n  position: absolute;\n  left: 0;\n  top: 0;\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  height: 18px;\n  pointer-events: none;\n  font-size: var(--fs-xs);\n  color: var(--muted);\n  white-space: nowrap;\n  user-select: none;\n}\n/* The word itself, in a pill: the two DELIVERY MODES as two greys — Queue is the quiet one\n   (--tool-bg, the same grey as a Queued badge) and Steer the raised one (--surface-2, its edge a\n   step up at --overlay-3). This is the pending bubbles' pairing repeated here on purpose: the\n   indicator and the row it describes must name the same mode with the same tone. No red and no\n   glow left in either — Steer is not an alarm, it is the same message arriving sooner. */\n#insert-hint-word {\n  display: inline-flex;\n  align-items: center;\n  height: 18px;\n  padding: 0 8px;\n  border-radius: 999px;\n  background: var(--tool-bg);\n  border: 1px solid var(--border);\n  color: var(--muted);\n  font-weight: 600;\n  line-height: 1;\n  transition:\n    background 0.18s,\n    color 0.18s,\n    border-color 0.18s,\n    box-shadow 0.18s;\n}\n#insert-hint.is-steer #insert-hint-word {\n  background: var(--surface-2);\n  border-color: var(--overlay-3);\n  color: var(--fg);\n}\n/* Idle (no run in flight): dimmed like the old disabled pill — the choice only means\n   something while the agent is working. */\n#insert-hint.is-idle {\n  opacity: 0.45;\n}\n#ctl-toggle-btn {\n  background: transparent;\n  border: none;\n  color: var(--accent);\n  padding: 3px 8px;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  transition:\n    color 0.12s,\n    transform 0.12s;\n  box-shadow: none;\n  filter: none;\n  line-height: 0;\n}\n#ctl-toggle:hover #ctl-toggle-btn {\n  color: var(--accent-strong);\n}\n#ctl-toggle-btn svg {\n  transition: transform 0.15s;\n}\nbody.controls-collapsed #ctl-toggle-btn svg {\n  transform: rotate(180deg);\n}\n/* Collapsed: hide ONLY the Window + Sampling cards. The AI Model row, the\n   ask card and the metrics row stay visible. #status wraps ONLY those\n   cards now (the model row lives in the ask box), so an empty 16px padded\n   box would double the gap to the metrics below — hide it and give the\n   metrics a single normal 8px gap instead. */\nbody.controls-collapsed #ctl-cards {\n  display: none;\n}\nbody.controls-collapsed #status {\n  display: none;\n}\nbody.controls-collapsed #metrics {\n  margin-top: 8px;\n}\n/* No stack to toggle -> the strip disappears too. */\nbody.no-session #ctl-toggle,\nbody.no-workspace #ctl-toggle {\n  display: none;\n}\n\n/* Symmetric padding (8px top/bottom) so the gap above and below the\n   status block is identical — in the collapsed form the 3 visible cards\n   (ask / AI Model / metrics) are then evenly spaced. */\n#status {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  padding: 8px 10px;\n  font-size: var(--fs-md);\n  /* The ONLY body child that yields when the panel is short: #messages-wrap\n     keeps its floor (chat), the prompt and the metrics keep their height, so\n     the control stack is what gives — and it SCROLLS (.ctl-cards), which is\n     exactly the trade the expanded cards are designed for. overflow:hidden is\n     the belt to that brace: a shrunk #status can never paint its cards over\n     the metrics below it. */\n  flex-shrink: 1;\n  min-height: 0;\n  overflow: hidden;\n}\n#status .warn {\n  color: var(--error);\n}\n/* Grouped cards: the grid collapses to a single column when the panel is\n   narrow, so fields are never squeezed or split mid-pair. minmax is font-\n   relative: on zoom-in the columns stack gracefully (responsive to both\n   panel width and font size). */\n.ctl-cards {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 8px;\n  /* Scrolls VERTICALLY only once it would take more than 75% of the panel\n     height — and never more than what still leaves the prompt, model row\n     and metrics their room, so the BOTTOM is the last thing to go. */\n  max-height: clamp(6rem, calc(100vh - 20rem), 75vh);\n  min-height: 0;\n  overflow-y: auto;\n  overflow-x: hidden;\n  overscroll-behavior: contain;\n  scrollbar-width: thin;\n  scrollbar-color: var(--scroll-thumb) transparent;\n}\n.ctl-cards::-webkit-scrollbar {\n  width: 8px;\n}\n.ctl-cards::-webkit-scrollbar-track {\n  background: transparent;\n}\n.ctl-cards::-webkit-scrollbar-thumb {\n  background: var(--scroll-thumb);\n  border-radius: 4px;\n}\n.ctl-cards::-webkit-scrollbar-thumb:hover {\n  background: var(--scroll-thumb-hover);\n}\n/* Narrow panel: stack the cards in ONE column, in DOM order (Window,\n   Sampling, Parallel, Loop Guard), so nothing is squeezed or split\n   mid-pair. The Loop Guard parameter fields collapse with it. */\n/* Static FALLBACK for the very first paint: the JS measures the nowrap\n   sensitivity row and sets the exact column count right after. */\n@media (max-width: 30rem) {\n  .ctl-cards {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .lg-fields {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n@media (min-width: 59rem) {\n  .ctl-cards {\n    grid-template-columns: repeat(4, minmax(0, 1fr));\n  }\n  .lg-fields {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n.ctl-card {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  border-radius: 8px;\n  padding: 8px 10px;\n  background: var(--input-bg);\n}\n/* The Guardrails card spans the full row (prompt width) instead of one grid\n   column: it holds the per-session run controls (parallel cap + Loop Guard). */\n.ctl-card-wide {\n  grid-column: 1 / -1;\n}\n/* Skills card: one clickable TEXT per installed skill (no button chrome);\n   a click fills the prompt with \"/skill <name> \". */\n#skills-list {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px 12px;\n}\n.skill-item {\n  cursor: pointer;\n  color: var(--accent);\n  font-size: var(--fs-sm);\n  max-width: 100%;\n  overflow-wrap: anywhere;\n}\n.skill-item:hover {\n  text-decoration: underline;\n}\n/* MCP card + editor modal (mirrors the providers editor).\n   ONE row per server, ONE line each: a long error (npm's log path, an HTTP body) used\n   to wrap to three lines and change the card's height, so the whole control stack moved\n   under the cursor every time a server was toggled. The full text stays in the tooltip. */\n#mcp-list {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n  min-width: 0;\n}\n.mcp-status {\n  font-size: var(--fs-sm);\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  min-width: 0;\n}\n.mcp-status.ok {\n  color: var(--ok);\n}\n.mcp-status.err {\n  color: var(--error, #f05555);\n}\n.mcp-status .mcp-name {\n  cursor: pointer;\n  flex: none;\n  white-space: nowrap;\n}\n/* The server's switch is THE control (.harny-switch, defined once at the top of this sheet): a\n   click on the NAME is a shortcut for it, which is why the name looks pressable. */\n.mcp-status .mcp-detail {\n  color: var(--muted-2);\n  flex: 1 1 auto;\n  min-width: 0;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n.mcp-status .mcp-tools-btn {\n  flex: none;\n}\n.mcp-tools-btn {\n  background: transparent;\n  border: none;\n  padding: 0;\n  cursor: pointer;\n  color: var(--accent);\n  font-size: var(--fs-sm);\n  text-decoration: underline;\n}\n.mcp-tools-btn:hover {\n  color: var(--accent-strong, var(--accent));\n}\n/* Tools panel: a floating card anchored to the (N tools) key, listing EVERY tool\n   of one server with the checkbox that decides what the MODEL sees. It is a\n   draft-until-Save editor (All / None / Cancel / Save), because saving reconnects\n   the server and a per-click reconnect would respawn a process each time. */\n#mcp-tools-popover {\n  position: fixed;\n  z-index: 60;\n  width: min(34rem, 92vw);\n  max-height: 60vh;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 8px 10px;\n  box-shadow: 0 6px 24px var(--modal-shadow);\n}\n#mcp-tools-popover.hidden {\n  display: none;\n}\n.mcp-pop-head {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n}\n.mcp-pop-title {\n  font-weight: 600;\n}\n.mcp-pop-count {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n.mcp-pop-filter {\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 3px 6px;\n  font-size: var(--fs-sm);\n}\n/* One line of explanation above the list: the two pills are identical on purpose, so the sentence\n   is what tells a reader which is which before they have to guess. */\n.mcp-pop-legend {\n  font-size: var(--fs-xs);\n  color: var(--muted-3);\n  line-height: 1.4;\n}\n.mcp-pop-list {\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow: auto;\n  display: flex;\n  flex-direction: column;\n}\n.mcp-pop-row {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  padding: 5px 0;\n  border-top: 1px solid var(--border);\n  cursor: pointer;\n}\n.mcp-pop-row:first-of-type {\n  border-top: none;\n}\n/* The row's controls are THE switch (.harny-switch): one look, one meaning — \"is this thing ON in\n   this conversation?\" — instead of a second visual language one card above the pill it duplicates.\n   Only the POSITION is this row's business: 3px down, so the 12px pill sits on the name's first\n   line rather than on a description's second. */\n.mcp-pop-row .harny-switch {\n  margin-top: 3px;\n  align-self: flex-start;\n}\n/* The Analyze cluster: the WORD plus the same pill, at the far right of the row and away from the\n   exposure switch on the left, because they answer different questions (\"may the model see it\" vs\n   \"may it run in Analyze\"). The label is not decoration: two identical pills side by side would be a\n   guessing game, and this one carries no state a reader could infer from the row. */\n.mcp-pop-analyze {\n  flex: none;\n  margin-left: auto;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  /* The whole cluster is a target (the word as much as the pill), like the row's name for exposure. */\n  cursor: pointer;\n}\n.mcp-pop-analyze-label {\n  font-size: var(--fs-xs);\n  letter-spacing: 0.02em;\n  text-transform: uppercase;\n  color: var(--muted-3);\n  white-space: nowrap;\n}\n/* ON means \"this tool may run in Analyze\", so the word lights with the pill: the colour is the second\n   signal after the knob, and it is what makes the state readable at a glance down the column. */\n.mcp-pop-analyze.on .mcp-pop-analyze-label {\n  color: var(--ok);\n}\n/* The server declares every tool of it read-only: the pill is on and not editable (the host says so\n   with `disabled`), and the label dims with it rather than claiming a decision of this conversation. */\n.mcp-pop-analyze.inherited {\n  cursor: default;\n}\n.mcp-pop-analyze.inherited .mcp-pop-analyze-label {\n  opacity: 0.55;\n}\n.mcp-pop-text {\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  min-width: 0;\n}\n.mcp-pop-name {\n  font-family: var(--font-mono);\n  font-size: var(--fs-sm);\n  color: var(--fg);\n}\n.mcp-pop-desc {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  overflow-wrap: anywhere;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n  overflow: hidden;\n}\n/* Excluded: dimmed, so the list reads as \"these are not there\" at a glance. */\n.mcp-pop-row.off .mcp-pop-name,\n.mcp-pop-row.off .mcp-pop-desc {\n  color: var(--muted-3);\n}\n.mcp-pop-empty {\n  color: var(--muted-2);\n  font-size: var(--fs-sm);\n}\n.mcp-pop-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.mcp-pop-status {\n  flex: 1 1 auto;\n  min-width: 0;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n.mcp-pop-status.err {\n  color: var(--error, #f05555);\n}\n.mcp-pop-mini {\n  padding: 2px 8px;\n  font-size: var(--fs-sm);\n}\n/* Slash menu: skill autocomplete above the prompt. Only shown when the\n   prompt STARTS with \"/\" and has no whitespace yet. */\n#slash-menu {\n  position: fixed;\n  z-index: 40;\n  max-height: 40vh;\n  overflow: auto;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 4px;\n  box-shadow: 0 6px 24px var(--modal-shadow);\n}\n#slash-menu.hidden {\n  display: none;\n}\n/* Find bar: floats over the transcript, top-right, so it never pushes the text around\n   (a moving transcript under a selection would defeat the point of searching). */\n#find-bar {\n  position: fixed;\n  z-index: 45;\n  top: 6px;\n  right: 10px;\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  padding: 4px 6px;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  box-shadow: 0 6px 24px var(--modal-shadow);\n}\n#find-bar.hidden {\n  display: none;\n}\n#find-bar input {\n  width: 12rem;\n  padding: 2px 6px;\n  font-size: var(--fs-sm);\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  min-height: 0;\n}\n#find-bar input:focus {\n  outline: 1px solid var(--accent);\n  outline-offset: 0;\n}\n#find-bar .find-count {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  min-width: 3.2rem;\n  text-align: center;\n}\n#find-bar .find-count.none {\n  color: var(--warn-soft, #d9a400);\n}\n/* Find highlights: painted by the CSS Custom Highlight API, NOT by the document selection —\n   a selection would blur the find field and you could not type past the first match. */\n::highlight(harny-find) {\n  background-color: var(--find-hit, rgba(255, 196, 0, 0.35));\n}\n::highlight(harny-find-current) {\n  background-color: var(--accent);\n  color: var(--on-accent, #fff);\n}\n#find-bar button {\n  padding: 0 6px;\n  font-size: var(--fs-sm);\n  min-height: 0;\n  line-height: 18px;\n}\n/* The transcript context menu (Copy / Select all): ours, so it exists on every OS. */\n#ctx-menu {\n  position: fixed;\n  z-index: 60;\n  min-width: 9rem;\n  padding: 4px;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  box-shadow: 0 6px 24px var(--modal-shadow);\n}\n#ctx-menu.hidden {\n  display: none;\n}\n#ctx-menu button {\n  display: block;\n  width: 100%;\n  text-align: left;\n  padding: 4px 8px;\n  font-size: var(--fs-sm);\n  background: transparent;\n  border: none;\n  border-radius: 6px;\n  color: var(--fg);\n  min-height: 0;\n  box-shadow: none;\n}\n#ctx-menu button:hover:not(:disabled) {\n  background: var(--overlay-1);\n}\n#ctx-menu button:disabled {\n  color: var(--muted-3);\n}\n.slash-item {\n  display: flex;\n  flex-direction: column;\n  gap: 1px;\n  padding: 5px 8px;\n  border-radius: 6px;\n  cursor: pointer;\n}\n.slash-item.active,\n.slash-item:hover {\n  background: var(--overlay-1);\n}\n.slash-cmd {\n  font-family: var(--font-mono);\n  font-size: var(--fs-md);\n  color: var(--fg);\n}\n.slash-desc {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  max-width: 100%;\n}\n/* Overlay geometry (viewport-locked fixed box, flex centring) comes from the\n   shared modal block further down; only the stacking order lives here. */\n#mcp-modal {\n  z-index: 50;\n}\n#mcp-modal.hidden {\n  display: none;\n}\n.mcp-backdrop {\n  background: var(--backdrop);\n}\n.mcp-card {\n  position: relative;\n  margin: auto;\n  width: min(46rem, 100%);\n  max-height: 100%;\n  overflow: auto;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  padding: 14px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n.mcp-head h3 {\n  margin: 0 0 2px;\n}\n.mcp-hint {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n.mcp-body {\n  display: flex;\n  gap: 12px;\n  align-items: flex-start;\n}\n.mcp-list-col {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  min-width: 11rem;\n}\n#mcp-select {\n  min-height: 9rem;\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 4px;\n}\n.mcp-list-actions {\n  display: flex;\n  gap: 6px;\n}\n.mcp-form-col {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.mcp-form-col input[type=\"text\"],\n.mcp-form-col textarea {\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 4px 6px;\n  font-size: var(--fs-md);\n}\n.mcp-form-col textarea {\n  font-family: var(--font-mono);\n  resize: vertical;\n}\n.mcp-form-actions {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n.mcp-enabled-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  cursor: pointer;\n}\n/* The enable flag is THE switch (.harny-switch): the one control in this form that turns a whole\n   SERVER on or off, and it must look like every other on/off control in the panel. Its own\n   dimensions and colours used to live here — that is exactly how it drifted away from the pill in\n   the tools popover. Only the LAYOUT is this row's business. */\n.mcp-enabled-row .harny-switch {\n  flex: none;\n}\n/* A disabled server is grayed out (name + detail). */\n.mcp-status.off,\n.mcp-status.off .mcp-name,\n.mcp-status.off .mcp-detail {\n  color: var(--muted-3);\n}\n.mcp-io {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n.mcp-io.ok {\n  color: var(--ok);\n}\n.mcp-io.err {\n  color: var(--error, #f05555);\n}\n.mcp-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\nbody.no-session #mcp-card,\nbody.no-workspace #mcp-card {\n  display: none;\n}\n/* Numeric rows (Window + Sampling): a SLIDER plus a read-only value label.\n   The label keeps the exact value; the slider is the control.\n   The LOOK of a slider is set in exactly ONE place — the pair of rules at the top of this sheet that\n   paints the track, the orange fill, the knob and the disabled state for both engines. A rule like\n   this one owns the ROW (how much space the control takes), never the control: `accent-color`,\n   `height`, `margin`, `cursor` and `:disabled` used to be repeated at every site, and with\n   `appearance: none` plus a thumb drawn by us, `accent-color` coloured nothing at all while the rest\n   were copies left free to drift apart one site at a time. */\n.num-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n  min-height: var(--ctl-row, 1.4rem);\n}\n.num-range {\n  flex: 1 1 auto;\n  min-width: 0;\n}\n/* ── THE NUMBER YOU CAN TYPE (src/chat/webview/num-field.ts) ──\n   The same slot the read-only label used to fill (same width, same right-aligned tabular figures),\n   so promoting a value to an input does not move a single pixel of the row. What it gains is an\n   AFFORDANCE and nothing else: `cursor: text`, a hairline under the digits on hover, and the accent\n   plus the panel's input background while focused. No border, no box, no fill at rest — beside a\n   slider, a framed field would read as a second control of equal weight instead of the same number\n   written differently. The focus RING is the panel's shared one (keyboard users get it, a mouse\n   click does not paint it), because the hairline alone is not a focus indicator. */\n.num-input {\n  flex: 0 0 auto;\n  /* WIDE ENOUGH FOR THE LONGEST THING A DOMAIN CAN HOLD: \"2000000\" — seven tabular digits, the\n     largest context window. The width is in `ch` on purpose, so it follows the FONT rather than a\n     hand-tuned rem: the old 3.6rem was measured against a text scale that this sheet never\n     actually declares (see the note on `--fs-*` at the top), so the box came out narrower than\n     the digits it was asked to show and clipped the number it exists to display. ONE width for\n     every site — window, output, sampler, parallel, Loop Guard, dialogs — because they are the\n     same control in different rows. */\n  width: calc(7ch + 12px);\n  min-width: 3.6rem;\n  padding: 1px 3px;\n  text-align: right;\n  font-size: var(--fs-xs);\n  font-variant-numeric: tabular-nums;\n  color: var(--fg);\n  background: transparent;\n  border: none;\n  border-bottom: 1px solid transparent;\n  border-radius: 3px;\n  cursor: text;\n}\n/* A blank box is the Auto state: the placeholder has to be READABLE (opacity 1 — browsers fade it),\n   and quiet enough not to be mistaken for a value. */\n.num-input::placeholder {\n  color: var(--muted-2);\n  opacity: 1;\n}\n.num-input:hover:not(:disabled) {\n  border-bottom-color: var(--overlay-3);\n}\n.num-input:focus {\n  outline: none;\n  border-bottom-color: var(--accent);\n  background: var(--input-bg);\n}\n.num-input:focus-visible {\n  outline: 1px solid var(--accent);\n  outline-offset: 1px;\n}\n.num-input:disabled {\n  opacity: 0.5;\n  cursor: default;\n  border-bottom-color: transparent;\n}\n/* ── THE UNIT BELONGS TO THE NUMBER ──\n   \"80\" alone is a reading, \"80%\" is the value — and in these rows the label is a sentence\n   (\"Auto-compaction trigger…\", \"Min reclaimable\"), so the unit cannot live there without being\n   read as prose. It rides INSIDE the number's own area instead: same figures, same baseline, a\n   step quieter in colour. It is decoration, NOT content: it never enters `.value`, so it cannot be\n   half-typed, deleted, selected or pasted away, and `num-field`'s mask never sees it. The inner\n   input drops its right padding so the unit sits flush against the digits — no gap to read as\n   \"the number, then something else\". */\n.num-slot {\n  display: inline-flex;\n  align-items: baseline;\n  flex: 0 0 auto;\n}\n.num-slot > .num-input {\n  padding-right: 0;\n}\n.num-unit {\n  font-size: var(--fs-xs);\n  font-variant-numeric: tabular-nums;\n  color: var(--muted-2);\n  user-select: none;\n}\n/* The Auto key, WHILE Auto: the mode lives in the KEY, not in the number — the box keeps showing\n   the value that will be stored, so there is nothing to blank out and nothing to explain twice. */\n.ctx-btn.is-on:not(:disabled) {\n  color: var(--accent);\n  border-color: var(--accent-line);\n}\n/* Loop Guard card: the sensitivity row wraps inside its half-width card. */\n/* The sensitivity row NEVER wraps: \"Include response\" always stays on the\n   SAME line as the High/Normal/Low radios. */\n#lg-toggle {\n  flex-wrap: nowrap;\n  min-height: var(--ctl-row, 1.4rem);\n  align-items: center;\n}\n#lg-toggle .sampler-opt {\n  white-space: nowrap;\n}\n/* Loop Guard card: the parameters section collapses via the chevron, which\n   sits on the SAME LINE as \"Include response\" (the last item of the\n   sensitivity group). Collapsed by default, so the card — and its grid-row\n   neighbour (Parallel) — stays at its minimum height. */\n#lg-params-field.hidden {\n  display: none;\n}\n/* The head row = radios + chevron. The radios CANNOT wrap, so they may only\n   shrink by clipping: min-width 0 + overflow hidden keep the chevron in\n   place instead of letting the text push it out of the card. */\n.lg-head {\n  display: flex;\n  align-items: flex-end;\n  gap: 8px;\n  min-width: 0;\n}\n#lg-toggle {\n  min-width: 0;\n  overflow: hidden;\n}\n.lg-collapse {\n  margin-left: auto;\n  flex: 0 0 auto;\n  background: transparent;\n  border: none;\n  padding: 1px;\n  cursor: pointer;\n  color: var(--muted);\n  line-height: 0;\n}\n.lg-collapse:hover {\n  color: var(--fg);\n}\n.lg-collapse svg {\n  transition: transform 0.15s ease;\n}\n.lg-collapse[aria-expanded=\"true\"] svg {\n  transform: rotate(180deg);\n}\n/* Shared hover tooltip: a small floating card that explains a parameter.\n   Positioned by the client; never intercepts the pointer. */\n.tip {\n  position: fixed;\n  /* The card is the TOPMOST thing in the panel, and it has to be: `data-tip` lives on controls\n     INSIDE modals too (the compact card's `Default` button, the sessions list, the providers\n     form), and a modal is `position: absolute` with its own `z-index` — a card below it is not\n     \"under\" a control, it is behind a semi-transparent veil, i.e. an explanation that silently\n     does not exist. The highest surface is `#alert-modal` at 110, so the card clears the whole\n     ladder (50 providers/mcp, 60 sessions, 70 model/vacuum, 100 compact, 110 alert); the test\n     reads every modal's z-index and fails if a new surface is added above this one. Nothing is\n     lost by being on top: `pointer-events: none` means it can never steal a click from the\n     modal it floats over. */\n  z-index: 120;\n  max-width: 21rem;\n  background: var(--surface-2);\n  color: var(--fg);\n  border: 1px solid var(--overlay-2);\n  border-radius: 6px;\n  padding: 6px 8px;\n  font-size: var(--fs-xs);\n  line-height: 1.35;\n  box-shadow: 0 6px 18px var(--key-shadow);\n  pointer-events: none;\n}\n.tip.hidden {\n  display: none;\n}\n/* EVERY explanation advertises itself the same way: the NAME of a parameter lights up while the\n   pointer is anywhere on its field, so the card is discoverable without a permanent ⓘ badge on a\n   panel this dense. NO underline: a dotted line under static text read as a link and made the\n   whole panel shimmer on every pass of the pointer. The label is the TARGET — the tooltip belongs\n   to the title of a parameter, not to the slider that sits under it.\n   Gated by `body.help-on` (the Interactive help switch): a lit name ADVERTISES a card, and with the\n   switch off there is no card to advertise. */\nbody.help-on .field:hover > .field-label[data-tip],\nbody.help-on .field:hover > .sampler-toggle > .sampler-opt[data-tip],\nbody.help-on .lg-field:hover .lg-name {\n  color: var(--fg);\n}\n/* `cursor: help` is for INERT text only (a parameter name). On a button it would erase the click\n   affordance, so it is opt-in per element — `data-tip` alone does not imply it. And it is gated by\n   the Interactive help switch: the attribute stays on the element (it is cheap and it is what\n   `tips.ts` decided), the POINTER is what the user asked for. One class on <body> turns every\n   question mark in the panel off at once, which no per-element loop can promise. */\nbody.help-on [data-tip][data-tip-cursor=\"help\"] {\n  cursor: help;\n}\n/* ── INTERACTIVE HELP: one switch for every explanation in the panel ──\n   The card and the question mark are a LEARNING AID, and a panel this dense does not always want\n   to teach: switched off — which is the DEFAULT, an explanation nobody asked for is noise — nothing\n   invites a detour, nothing changes shape under the pointer, and the interface is exactly what an\n   expert asked for. The switch itself is the ONE element that keeps explaining itself\n   (`data-tip-always`) — an OFF state where nothing answers would be a switch with no way back. It\n   sits BEFORE the + because it governs the PANEL, not the session list under it. Muted when off,\n   accent when on: the state is readable at a glance, like the folds. */\n#session-head .help-toggle {\n  width: 16px;\n  height: 16px;\n  min-height: 0;\n  padding: 0;\n  border-radius: 50%;\n  font-size: var(--fs-sm);\n  font-weight: 700;\n  line-height: 1;\n  color: var(--muted-2);\n}\n#session-head .help-toggle[aria-pressed=\"true\"] {\n  color: var(--accent);\n  background: var(--accent-tint-soft);\n}\n#session-head .help-toggle[aria-pressed=\"true\"]:hover {\n  background: var(--accent-surface);\n}\n/* Loop Guard FIELDS: the preset values exposed as editable sliders, SAVED\n   per session (only the sensitivity level and these values are stored). */\n.lg-fields {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 6px 10px;\n}\n.lg-field {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  grid-template-areas: \"name val\" \"range range\";\n  gap: 2px 6px;\n  align-items: center;\n  min-width: 0;\n  font-size: var(--fs-xs);\n  color: var(--muted-2);\n}\n.lg-name {\n  grid-area: name;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n/* The value is a read-only LABEL (the slider is the only control). */\n.lg-value {\n  grid-area: val;\n  text-align: right;\n  color: var(--fg);\n  font-variant-numeric: tabular-nums;\n}\n.lg-range {\n  /* LOOK: the shared range rules at the top of the sheet. Here only the GRID SLOT this control\n     fills — it shares its row with the parameter's name and its value label. */\n  grid-area: range;\n  width: 100%;\n}\n/* Loop Guard OFF: the parameter sliders are inert (they stay in place, with their\n   values, so switching level never changes the card's height — the column-count\n   measurement reads this row). Dim the whole block, labels included. */\n#lg-fields.is-off {\n  opacity: 0.45;\n}\n.lg-field input:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n.ctl-inline {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  min-width: 0;\n}\n/* The AI Model card keeps the ORIGINAL proportions: one full-width row\n   with the label inline and the select stretching (card chrome only). */\n.ctl-card-model {\n  flex-direction: row;\n  align-items: center;\n  gap: 8px;\n}\n/* Inside the prompt area the AI Model row drops the card chrome (the box\n   is the input area itself) and becomes a plain head row above the prompt.\n   The mode button lives HERE on the same line as the model select; the\n   extra top margin opens breathing room below the prompt row above. */\n#input-area .ctl-card-model {\n  background: transparent;\n  border-radius: 0;\n  padding: 0;\n  gap: 8px;\n  margin-top: 10px;\n}\n\n/* Mode select (Analyze / Agent): ONE compact pill button showing the\n   current mode; clicking opens a small VERTICAL dropdown with the two\n   choices. It sits on the AI Model row, next to the other controls, so it\n   follows THEIR visual language — quiet dark pill, light-gray label, muted\n   chevron — and carries the mode in the COLOUR OF ITS ICON (terracotta for\n   Analyze, violet for Agent: the same pair the dropdown items use). A white\n   icon + label on a saturated gradient made the row's quietest element\n   shout loudest. The dropdown is anchored to the button (z-index keeps it\n   above the cards). */\n#mode-select {\n  position: relative;\n  width: max-content;\n  max-width: 100%;\n  flex-shrink: 0;\n  user-select: none;\n}\n#mode-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  min-width: 0;\n  height: 1.85rem;\n  padding: 0 9px 0 8px;\n  border: 1px solid var(--border);\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--fg);\n  font-size: var(--fs-sm);\n  font-weight: 600;\n  letter-spacing: 0.01em;\n  cursor: pointer;\n  white-space: nowrap;\n  box-shadow: inset 0 1px 2px var(--sink-1);\n  transition:\n    background 0.18s,\n    box-shadow 0.18s,\n    color 0.18s,\n    border-color 0.18s,\n    transform 0.12s,\n    opacity 0.18s;\n}\n#mode-btn:hover {\n  border-color: var(--overlay-4);\n  color: var(--fg-strong);\n}\n#mode-btn:active {\n  transform: scale(0.96);\n}\n#mode-btn:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: 2px;\n}\n#mode-btn:disabled {\n  opacity: 0.45;\n  cursor: default;\n  transform: none;\n  box-shadow: none;\n}\n/* NO colour carries the mode in ANALYZE (the quiet default): both icons are the\n   muted gray of the other pills on this row, and the LABEL is what says which mode\n   you are in. BUILD is the loud one ON PURPOSE — see the .is-agent block below. */\n#mode-btn-icon-analyze,\n#mode-btn-icon-agent {\n  flex-shrink: 0;\n  color: var(--muted);\n  transition: color 0.18s;\n}\n#mode-btn:hover #mode-btn-icon-analyze,\n#mode-btn:hover #mode-btn-icon-agent {\n  color: var(--fg);\n}\n#mode-btn-icon-analyze.hidden,\n#mode-btn-icon-agent.hidden {\n  display: none;\n}\n/* ONE width for BOTH modes: the longest label (\"Analyze\") is reserved by an in-flow,\n   zero-height ghost, so switching mode can never move this pill — or the two that sit\n   next to it. A flex item's base size IS the max-content of its content, so the ghost\n   is all it takes; measuring at runtime would cost a layout on every switch and would\n   still reflow on the way back. The string is the LONGEST of the two choices below. */\n#mode-btn-label::before {\n  content: \"Analyze\";\n  display: block;\n  height: 0;\n  visibility: hidden;\n}\n/* Chevron rotates when the dropdown is open. */\n#mode-btn .mode-btn-chevron {\n  flex-shrink: 0;\n  color: var(--muted);\n  transition:\n    color 0.18s,\n    transform 0.18s;\n}\n#mode-btn:hover .mode-btn-chevron {\n  color: var(--fg);\n}\n/* BUILD: one orange pill says \"tools write for real\" BEFORE you send anything.\n   Analyze keeps the quiet gray above, so the contrast IS the signal — you never\n   have to re-read the word to know which mode the next run uses. Same recipe as\n   #parallel-btn.is-on (saturated gradient, white icon+label, soft glow). These\n   rules must stay AFTER the neutral ones: #mode-btn:hover has the same\n   specificity, so the ORDER is what makes the orange win on hover too. */\n#mode-btn.is-agent {\n  background: linear-gradient(135deg, var(--accent), var(--accent-strong));\n  border-color: transparent;\n  color: #ffffff;\n  box-shadow:\n    0 1px 2px var(--key-shadow),\n    0 0 12px var(--accent-glow);\n}\n#mode-btn.is-agent:hover {\n  border-color: transparent;\n  color: #ffffff;\n  box-shadow:\n    0 1px 3px var(--key-shadow),\n    0 0 16px var(--accent-glow-strong);\n}\n#mode-btn.is-agent #mode-btn-icon-analyze,\n#mode-btn.is-agent #mode-btn-icon-agent,\n#mode-btn.is-agent .mode-btn-chevron {\n  color: #ffffff;\n}\n/* The hover variants need their own rule: #mode-btn:hover #mode-btn-icon-agent\n   counts TWO ids and would repaint the icon gray on top of the white. */\n#mode-btn.is-agent:hover #mode-btn-icon-analyze,\n#mode-btn.is-agent:hover #mode-btn-icon-agent,\n#mode-btn.is-agent:hover .mode-btn-chevron {\n  color: #ffffff;\n}\n/* A policy changed under the panel keeps its dashed edge — a transparent border\n   would swallow it (same fix as #parallel-btn.is-on.is-pending). */\n#mode-btn.is-agent.is-pending {\n  border-style: dashed;\n  border-color: rgba(255, 255, 255, 0.6);\n}\n#mode-select.open #mode-btn .mode-btn-chevron {\n  transform: rotate(180deg);\n}\n/* The vertical dropdown: stacks the two choices under the button. */\n#mode-menu {\n  position: absolute;\n  top: calc(100% + 4px);\n  left: 0;\n  min-width: 100%;\n  z-index: 40;\n  display: flex;\n  flex-direction: column;\n  padding: 3px;\n  border-radius: 10px;\n  background: var(--surface-2);\n  border: 1px solid var(--border);\n  box-shadow: 0 8px 20px var(--modal-shadow);\n}\n#mode-menu.hidden {\n  display: none;\n}\n.mode-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  padding: 5px 10px;\n  border: none;\n  border-radius: 7px;\n  background: transparent;\n  color: var(--fg);\n  font-size: var(--fs-sm);\n  font-weight: 600;\n  cursor: pointer;\n  text-align: left;\n  white-space: nowrap;\n  transition:\n    background-color 0.1s,\n    color 0.1s;\n}\n.mode-item:hover {\n  background: var(--tool-bg);\n  color: var(--fg-strong);\n}\n.mode-item:focus-visible {\n  outline: 2px solid var(--accent);\n  outline-offset: -2px;\n}\n.mode-item.is-active {\n  color: var(--fg-strong);\n}\n/* The menu follows the button: NEUTRAL icons, and the accent marks only WHAT IS\n   SELECTED (the checkmark) — never which mode it is. */\n.mode-item svg:not(.mode-check) {\n  color: var(--muted);\n}\n.mode-item.is-active:not(:hover) {\n  background: var(--overlay-1);\n}\n.mode-check {\n  margin-left: 2px;\n  flex-shrink: 0;\n  visibility: hidden;\n}\n.mode-item.is-active .mode-check {\n  visibility: visible;\n  color: var(--accent);\n}\n\n/* Parallel toggle: press/release button right after the mode button.\n   Released = quiet dark pill; PRESSED = blue with white icon + label. */\n#parallel-btn {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  height: 1.85rem;\n  padding: 0 10px 0 8px;\n  border: 1px solid var(--border);\n  border-radius: 999px;\n  background: var(--surface-2);\n  color: var(--fg);\n  font-size: var(--fs-sm);\n  font-weight: 600;\n  cursor: pointer;\n  white-space: nowrap;\n  flex-shrink: 0;\n  box-shadow: inset 0 1px 2px var(--sink-1);\n  transition:\n    background 0.18s,\n    box-shadow 0.18s,\n    color 0.18s,\n    border-color 0.18s,\n    opacity 0.18s;\n}\n#parallel-btn svg {\n  flex-shrink: 0;\n  color: var(--muted);\n  transition: color 0.18s;\n}\n#parallel-btn:hover {\n  border-color: var(--overlay-4);\n  color: var(--fg-strong);\n}\n#parallel-btn:hover svg {\n  color: var(--fg);\n}\n#parallel-btn:focus-visible {\n  outline: 2px solid #4c8dff;\n  outline-offset: 2px;\n}\n#parallel-btn:disabled {\n  opacity: 0.45;\n  cursor: default;\n  box-shadow: none;\n}\n/* A Mode/Parallel policy that changed UNDER the panel while a run works (a config push,\n   another window): the pill is disabled — the run keeps the policy it was born with — so\n   the choice is PENDING, and the dashed border with its tooltip says exactly that. */\n#mode-btn.is-pending,\n#parallel-btn.is-pending {\n  border-style: dashed;\n}\n/* Parallel ON paints its border transparent, which would swallow the dashes. */\n#parallel-btn.is-on.is-pending {\n  border-color: rgba(255, 255, 255, 0.55);\n}\n#parallel-btn.is-on {\n  background: linear-gradient(135deg, #4c8dff, #2f6fed);\n  border-color: transparent;\n  color: #ffffff;\n  box-shadow:\n    0 1px 2px var(--key-shadow),\n    0 0 12px rgba(76, 141, 255, 0.4);\n}\n#parallel-btn.is-on svg {\n  color: #ffffff;\n}\n#parallel-btn.is-on:hover {\n  box-shadow:\n    0 1px 3px var(--key-shadow),\n    0 0 16px rgba(76, 141, 255, 0.55);\n}\n\n.card-title {\n  font-size: var(--fs-xs);\n  font-weight: 700;\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--muted-3);\n  user-select: none;\n}\n.field {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n}\n/* ONE control-row height for the whole control stack: label rows, slider\n   rows and radio groups all share it, so the LEFT and RIGHT columns line up\n   horizontally. Deliberately small, so nothing looks padded. */\n#ctl-cards {\n  --ctl-row: 1.4rem;\n}\n#ctl-cards .field-label {\n  display: flex;\n  align-items: center;\n  min-height: var(--ctl-row);\n}\n.field-label {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n/* \"(min → max)\" of the selected control, shown next to its label/radio. */\n.range-label {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  font-weight: 400;\n}\n/* Working state: the PLAY (send) button blinks in sync with the chat's\n   \"Working...\" bubble — same harny-pulse 1.2s animation, applied in the\n   same tick (send/compactStart), so the two pulse together. */\n#send-btn.blinking {\n  animation: harny-pulse 1.2s ease-in-out infinite;\n}\n/* Model selector: a BUTTON (not a native <select>) that opens the\n   filterable \"Select model\" modal. */\n.model-btn {\n  flex: 1;\n  min-width: 0;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  background: transparent;\n  color: inherit;\n  border: none;\n  outline: none;\n  font-size: var(--fs-md);\n  cursor: pointer;\n  height: 1.85rem;\n  text-align: left;\n}\n.model-btn:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n.model-btn:hover:not(:disabled) #model-btn-label {\n  color: var(--accent);\n}\n#model-btn-label {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  align-items: baseline;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* The gateway, in front of the model it serves: upper-cased and dimmed so it reads as an eyebrow\n   and never competes with the model name. `flex: none` on purpose — the provider is the word that\n   makes a model unambiguous, so it must not be the part the ellipsis eats. */\n#model-btn-label .mb-provider {\n  flex: none;\n  text-transform: uppercase;\n  font-size: 0.9em;\n  letter-spacing: 0.05em;\n  opacity: 0.62;\n}\n\n#model-btn-label .mb-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.model-btn.placeholder #model-btn-label {\n  color: var(--muted);\n  font-style: italic;\n}\n.model-btn .model-btn-chevron {\n  flex: none;\n  color: var(--muted);\n}\n#thinking-select {\n  width: 100%;\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  outline: none;\n  font-size: var(--fs-md);\n  cursor: pointer;\n  padding: 0 6px;\n  height: 1.85rem;\n}\n#thinking-select option {\n  color: #1e1e1e;\n}\n#thinking-select:disabled {\n  opacity: 0.45;\n  cursor: default;\n}\n#status .model-label,\n#input-area .model-label {\n  color: var(--muted-2);\n}\n/* The stepper fills its card field; the −/+ keys stay a tight unit inside. */\n#ctx-window,\n#out-window,\n#samp-window,\n#presence-window,\n#freq-window,\n#par-window {\n  display: inline-flex;\n  align-items: center;\n  gap: 2px;\n  width: 100%;\n}\n#ctx-input,\n#out-input,\n#samp-input,\n#presence-input,\n#freq-input,\n#par-input {\n  flex: 1;\n  min-width: 2.5rem;\n  width: auto;\n  height: 1.85rem;\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 1px 6px;\n  font-size: var(--fs-md);\n  text-align: right;\n}\n#ctx-input:focus,\n#out-input:focus,\n#samp-input:focus,\n#presence-input:focus,\n#freq-input:focus,\n#par-input:focus {\n  border-color: var(--accent);\n  outline: none;\n}\n/* Empty float input = Auto (not sent): neutral italic hint. */\n#samp-input::placeholder,\n#presence-input::placeholder,\n#freq-input::placeholder {\n  color: var(--muted-3);\n  font-style: italic;\n}\n/* Sampler selector: native radios on ONE slim row occupying the same\n   slot/height as the other field labels (no pill, no box). */\n.sampler-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n  row-gap: 4px;\n  min-height: var(--ctl-row, 1.4rem);\n}\n.sampler-opt {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  cursor: pointer;\n  user-select: none;\n  transition: color 0.12s;\n}\n.sampler-opt input[type=\"radio\"] {\n  accent-color: var(--accent);\n  margin: 0;\n  width: 9px;\n  height: 9px;\n  cursor: pointer;\n}\n/* The Loop Guard \"Include response\" flag shares the sampler row styling. Its SWITCH is the shared\n   control (.harny-switch) — the sizes it used to carry (11px tick beside 9px radios) made one\n   on/off question look like a different species from the pill in the MCP card. */\n.sampler-opt .harny-switch {\n  flex: 0 0 auto;\n}\n.sampler-opt:hover {\n  color: var(--fg);\n}\n.sampler-opt:has(input:checked) {\n  color: var(--accent);\n  font-weight: 600;\n}\n/* Metrics row: same font, label style and horizontal padding as the status\n   row above, so \"Tokens:\" lines up with \"AI Model:\". */\n/* Usage footer: a full-width card matching the control cards above. */\n#metrics {\n  display: flex;\n  flex-direction: column;\n  /* Same rule as #input-area: fixed chrome, never squeezed. */\n  flex-shrink: 0;\n  gap: 6px;\n  border-radius: 8px;\n  padding: 8px 10px;\n  margin: 0 10px 8px;\n  color: var(--muted-2);\n  background: var(--input-bg);\n}\n.metrics-stats {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex-wrap: wrap;\n  font-size: var(--fs-sm);\n}\n.metrics-stats .model-label {\n  color: var(--muted-2);\n}\n.metrics-stats .met {\n  white-space: nowrap;\n}\n.met-sep {\n  color: var(--muted-3);\n}\n#met-pct {\n  padding: 0 6px;\n  border: 1px solid var(--border);\n  border-radius: 10px;\n  background: var(--overlay-1);\n}\n#met-pct.warn {\n  color: var(--error);\n  border-color: var(--error);\n  background: rgba(244, 71, 71, 0.1);\n}\n#met-cache {\n  white-space: nowrap;\n  color: var(--accent);\n}\n/* The declared window, HUGGING the usable value: \"663.3k / 616k/1M (100%)\".\n   Both live inside ONE flex item (see the .met wrapper in the markup), so a\n   narrow panel can never wrap them apart — \"/1M\" alone on a line would be\n   meaningless. Dim and smaller than the value it qualifies: it explains the\n   number, it must not compete with it. Hidden while empty, so a session with\n   no reserve shows nothing at all. */\n.met-note {\n  white-space: nowrap;\n  color: var(--muted-3);\n  font-size: var(--fs-sm);\n}\n#met-window:empty {\n  display: none;\n}\n/* Placeholder state: provider does not report cached tokens. */\n#met-cache.idle {\n  color: var(--muted);\n}\n/* The bar is the hero: a full-width row of its own. The Compact key lives\n   in the stats row above, right after the cache indicator. */\n#ctx-bar-wrap {\n  width: 100%;\n  height: 8px;\n  border-radius: 4px;\n  background: var(--tool-bg);\n  border: 1px solid var(--border);\n  overflow: hidden;\n  box-shadow: inset 0 1px 2px var(--sink-1);\n}\n#ctx-bar {\n  height: 100%;\n  width: 0%;\n  border-radius: 4px;\n  transition: width 0.3s;\n  background-color: var(--accent);\n  background-image: linear-gradient(to bottom, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0) 55%);\n}\n#ctx-bar.warn {\n  background-color: var(--error);\n}\n/* Compact: a compact action key, inline after the cache indicator but\n   pushed to the right edge of the stats row. */\n#compact-btn {\n  flex: 0 0 auto;\n  width: auto;\n  white-space: nowrap;\n  margin-left: auto;\n  background: linear-gradient(to bottom, var(--overlay-2), var(--overlay-1)), var(--tool-bg, transparent);\n  border: 1px solid var(--border);\n  color: var(--fg);\n  border-radius: 6px;\n  padding: 4px 8px;\n  font-size: var(--fs-sm);\n  cursor: pointer;\n  box-shadow:\n    inset 0 1px 0 var(--overlay-3),\n    inset 0 -1px 0 var(--sink-1),\n    0 1px 2px var(--key-shadow);\n  transition:\n    color 0.12s,\n    border-color 0.12s,\n    box-shadow 0.12s,\n    transform 0.08s;\n}\n#compact-btn:hover:not(:disabled) {\n  color: var(--accent);\n}\n#compact-btn:active:not(:disabled) {\n  transform: translateY(1px);\n  box-shadow: inset 0 1px 3px var(--key-shadow);\n}\n/* The gear keys are styled by the shared .gear-btn rule (same graphic and\n   size everywhere) — see below. */\n#compact-threshold-label {\n  flex: 0 0 auto;\n  white-space: nowrap;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n#compact-btn:disabled {\n  opacity: 0.4;\n}\n\n/* Empty shell (no open session): hide the whole control stack and show a\n   hero that pushes the user to pick a session or create a new one. */\nbody.no-session #input-area,\nbody.no-session #status,\nbody.no-session #pending-section,\nbody.no-session #metrics {\n  display: none;\n}\n/* No single workspace: the control stack goes, the SESSIONS CARD STAYS. Sessions are\n   bucketed per workspace, so with no folder there is nothing to chat with — but the\n   history does not need a folder, and it is what tells you WHICH workspace to open.\n   The card is the workspace picker here (see renderHomeRow) and the hero names the\n   action. Takes precedence over no-session. */\nbody.no-workspace #tabs,\nbody.no-workspace #input-area,\nbody.no-workspace #status,\nbody.no-workspace #pending-section,\nbody.no-workspace #metrics {\n  display: none;\n}\n/* All sessions would be the SAME list as the card above: the form has no job here. */\nbody.no-workspace #sessions-gear-btn {\n  display: none;\n}\n/* The prompt is gone, so the list may use the room it left — but never so much that the\n   hero below it is squeezed out: this state's message is the point. */\nbody.no-workspace #sessions {\n  max-height: 45vh;\n}\n/* Point the eye up at the sessions list: the second path to act. */\nbody.no-session #session-head {\n  color: var(--accent);\n}\n.empty-hero {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  /* SAFE CENTER: centred when it FITS, top-aligned when it does not. A plain\n     centering clips the top of an overflowing flex container — on a short panel the\n     message (\"… no longer exists\") was pushed out of reach while the button stayed\n     visible, which is how a clear state reads as a mystery. */\n  justify-content: safe center;\n  gap: 8px;\n  padding: 24px;\n  text-align: center;\n  color: var(--muted-2);\n}\n.empty-hero .empty-icon {\n  font-size: var(--fs-hero);\n}\n/* Brand mark in place of the emoji, loaded from media/icon.svg (see\n   state.logoUri): the artwork lives in ONE file, no inlined duplicate.\n   An <img> can't inherit currentColor, so it shows the SVG's own colors. */\n.empty-hero .empty-logo img {\n  width: var(--fs-logo);\n  height: var(--fs-logo);\n  display: block;\n}\n.empty-hero .empty-logo:hover img {\n  opacity: 0.85;\n}\n.empty-hero h2 {\n  margin: 0;\n  font-size: var(--fs-xl);\n  color: var(--fg-strong);\n  font-weight: 700;\n}\n.empty-hero .empty-version {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n  margin-top: -2px;\n}\n/* Publisher credit. VS Code opens http(s) webview links in the system\n   browser itself, so this needs no message plumbing (verified in\n   workbench.desktop.main.js: onDidClickLink -> openerService.open). */\n.empty-hero .empty-version a.brand-link {\n  color: inherit;\n  text-decoration: none;\n}\n.empty-hero .empty-version a.brand-link:hover {\n  color: var(--accent);\n  text-decoration: underline;\n}\n.empty-hero p {\n  margin: 0;\n  font-size: var(--fs-md);\n  line-height: 1.5;\n}\n.empty-hero .empty-hint {\n  font-size: var(--fs-sm);\n}\n.empty-hero .empty-cta {\n  margin-top: 12px;\n  padding: 6px 20px;\n  font-size: var(--fs-lg);\n  border-radius: 6px;\n}\n@keyframes harny-empty-in {\n  from {\n    opacity: 0;\n    transform: translateY(6px);\n  }\n  to {\n    opacity: 1;\n    transform: none;\n  }\n}\nbody.no-session .empty-hero {\n  animation: harny-empty-in 0.25s ease-out;\n}\n.ctx-btn {\n  width: 1.38rem;\n  height: 1.38rem;\n  padding: 0;\n  font-size: var(--fs-lg);\n  line-height: 1;\n  background: linear-gradient(to bottom, var(--overlay-3), var(--overlay-1)), var(--tool-bg, transparent);\n  border: 1px solid var(--border);\n  color: var(--fg);\n  border-radius: 4px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  box-shadow:\n    inset 0 1px 0 var(--overlay-3),\n    inset 0 -1px 0 var(--sink-1),\n    0 1px 2px var(--key-shadow);\n}\n.ctx-btn:hover:not(:disabled) {\n  color: var(--accent);\n}\n.ctx-btn:active:not(:disabled) {\n  transform: translateY(1px);\n  box-shadow: inset 0 1px 3px var(--key-shadow);\n}\n/* ONE gear action across the cards (sessions head, model row, compaction\n   metrics): identical graphic and size everywhere — a bare, muted icon\n   (14×14 SVG) that turns accent on hover. The #session-head .gear-btn\n   selector beats the header's accent-colored button rule by specificity. */\n.gear-btn,\n#session-head .gear-btn {\n  flex: 0 0 auto;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 1.6rem;\n  height: 1.6rem;\n  padding: 0;\n  background: transparent;\n  border: none;\n  border-radius: 4px;\n  color: var(--muted);\n  font-size: inherit;\n  line-height: 1;\n  cursor: pointer;\n  transition:\n    color 0.12s,\n    background-color 0.12s;\n}\n.gear-btn:hover:not(:disabled),\n#session-head .gear-btn:hover:not(:disabled) {\n  color: var(--accent);\n  background: var(--overlay-1);\n}\n.gear-btn:disabled,\n#session-head .gear-btn:disabled {\n  opacity: 0.5;\n  cursor: default;\n}\n/* Providers & Models modal (gear editor). */\n#providers-modal {\n  z-index: 50;\n}\n#providers-modal.hidden {\n  display: none;\n}\n#providers-modal .providers-backdrop {\n  background: var(--backdrop);\n}\n#providers-modal .providers-card {\n  position: relative;\n  margin: auto;\n  width: min(700px, 100%);\n  max-height: 100%;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 18px 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  box-shadow: 0 8px 30px var(--modal-shadow);\n  font-size: var(--fs-lg);\n}\n#providers-modal h3 {\n  margin: 0;\n  font-size: var(--fs-xl);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n.providers-head {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.providers-hint {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n}\n.providers-body {\n  display: grid;\n  grid-template-columns: 190px 1fr;\n  gap: 16px;\n  min-height: 0;\n  flex: 1;\n}\n.provider-list-col {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  min-height: 0;\n}\n.provider-list-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n#provider-select {\n  width: 100%;\n  flex: 1;\n  min-height: 160px;\n  background: var(--input-bg, #252526);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  color: var(--fg);\n  font-size: var(--fs-lg);\n  padding: 2px;\n}\n#provider-select option {\n  padding: 3px 6px;\n}\n#provider-select option:checked {\n  background: var(--accent, #3794ff);\n  color: #fff;\n}\n.provider-form-col {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  min-width: 0;\n  overflow-y: auto;\n}\n.provider-form-col .field-label {\n  font-size: var(--fs-md);\n}\n/* API key: masked by default; the eye reveals it ONLY while held down. */\n.pe-secret {\n  position: relative;\n  display: flex;\n  align-items: center;\n}\n.pe-secret input {\n  flex: 1;\n  padding-right: 2.2rem;\n}\n.pe-secret .pe-eye {\n  position: absolute;\n  right: 4px;\n  top: 50%;\n  transform: translateY(-50%);\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 1.6rem;\n  height: 1.6rem;\n  min-height: 0;\n  padding: 0;\n  background: transparent;\n  border: none;\n  box-shadow: none;\n  color: var(--muted);\n  cursor: pointer;\n}\n.pe-secret .pe-eye:hover {\n  color: var(--accent);\n  filter: none;\n}\n.pe-secret .pe-eye:active {\n  transform: translateY(-50%);\n  box-shadow: none;\n  filter: none;\n}\n.provider-form-col input,\n.provider-form-col select {\n  font-size: var(--fs-lg);\n  padding: 5px 8px;\n  border-radius: 5px;\n  background: var(--input-bg, #252526);\n  border: 1px solid var(--border);\n  color: var(--fg);\n}\n.provider-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.provider-actions .danger {\n  color: var(--error, #f05555);\n}\n.providers-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 10px;\n}\n.providers-actions button {\n  font-size: var(--fs-lg);\n  padding: 6px 14px;\n  border-radius: 6px;\n}\n/* Import/export feedback: its OWN row UNDER the button strip. It used to be\n   a span inside .providers-actions, where a long absolute path (\"Imported\n   from /Users/…/harny-providers.json\") squeezed the buttons and shoved\n   Cancel/Save sideways. Full width + wrapping, and no empty gap while it\n   has nothing to say. */\n.providers-io {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n  overflow-wrap: anywhere;\n}\n.providers-io:empty {\n  display: none;\n}\n.providers-io.ok {\n  color: var(--ok);\n}\n.providers-io.err {\n  color: var(--error, #f05555);\n}\n#provider-test-result {\n  font-size: var(--fs-md);\n  line-height: 1.5;\n  border-radius: 6px;\n  padding: 8px 10px;\n  background: var(--overlay-1);\n  word-break: break-all;\n}\n#provider-test-result.ok {\n  color: var(--ok);\n}\n#provider-test-result.err {\n  color: var(--error, #f05555);\n}\n\n/* The Auto reset is a SEPARATE key, clearly detached from the + spinner. */\n#samp-auto,\n#presence-auto,\n#freq-auto {\n  margin-left: 6px;\n  width: auto;\n  padding: 0 0.5rem;\n}\n/* Hide the browser's native number spinners; we use our own − / + buttons. */\n#ctx-input::-webkit-outer-spin-button,\n#ctx-input::-webkit-inner-spin-button,\n#out-input::-webkit-outer-spin-button,\n#out-input::-webkit-inner-spin-button {\n  -webkit-appearance: none;\n  margin: 0;\n}\n#ctx-input,\n#out-input {\n  -moz-appearance: textfield;\n}\n\n/* ── Modal forms: ONE geometry, shared by every dialog ──\n   What these dialogs must do (Providers & Models, Select model, All\n   sessions, MCP, Compact, name/confirm prompts): stay in the PANEL's\n   coordinate space, not the viewport's. The panel has a width FLOOR (see\n   the note at the top of this sheet): below it the window grows a\n   horizontal bar instead of squeezing the controls. A dialog pinned to the\n   viewport (position: fixed) does NOT know about that floor — it kept\n   shrinking with the visible slice, so the Providers form got squeezed to\n   a sliver while the panel below still laid out at its floor, and the card\n   re-centred every time the bar appeared. The dialog is therefore laid out\n   against the BODY (which IS the panel content, body being position:\n   relative), with inset: 0: same width as the floor, same origin, and it\n   scrolls away together with the rest of the panel when the horizontal bar\n   is dragged — exactly like the content underneath it.\n   Card centring: flex + margin: auto. The auto margins still centre, but\n   they collapse to 0 when a card is taller than the screen, so its first\n   field stays reachable instead of being clipped above the top edge;\n   overflow: auto then scrolls the DIALOG, never the window. Backdrops stay\n   FIXED: they must keep covering the visible slice while the dialog itself\n   scrolls with the content. */\n#name-modal,\n#alert-modal,\n#compact-settings-modal,\n#providers-modal,\n#sessions-modal,\n#model-modal,\n#db-vacuum-modal,\n#mcp-modal {\n  position: absolute;\n  inset: 0;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 10px;\n  overflow: auto;\n  overscroll-behavior: contain;\n}\n#name-modal .name-modal-backdrop,\n#alert-modal .alert-backdrop,\n#compact-settings-modal .cs-backdrop,\n#providers-modal .providers-backdrop,\n#sessions-modal .sm-backdrop,\n#model-modal .mm-backdrop,\n#db-vacuum-modal .dv-backdrop,\n#mcp-modal .mcp-backdrop {\n  position: fixed;\n  inset: 0;\n}\n\n/* ── Session-name modal (in the Harny panel): full-area overlay, blurred ── */\n#name-modal {\n  z-index: 100;\n}\n#name-modal.hidden {\n  display: none;\n}\n#name-modal .name-modal-backdrop {\n  background: var(--backdrop);\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n}\n#name-modal .name-modal-card {\n  position: relative;\n  margin: auto;\n  max-height: 100%;\n  overflow: auto;\n  width: min(340px, 100%);\n  background: var(--bg);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 14px;\n  box-shadow: 0 8px 30px var(--key-shadow);\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n#name-modal h3 {\n  margin: 0;\n  font-size: var(--fs-lg);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n#name-modal #name-input {\n  width: 100%;\n  margin-top: 8px;\n  box-sizing: border-box;\n}\n#name-modal #name-error {\n  margin-top: 6px;\n  min-height: 1em;\n  font-size: var(--fs-sm);\n  color: var(--error);\n  word-wrap: break-word;\n}\n#name-modal #name-error:empty {\n  display: none;\n}\n#name-input {\n  width: 100%;\n  background: var(--input-bg);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 6px 8px;\n  font-size: var(--fs-lg);\n  outline: none;\n  box-sizing: border-box;\n}\n#name-input:focus {\n  border-color: var(--accent);\n}\n#name-modal .name-modal-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\n\n/* ── Compaction policy (gear after Compact): trigger % + landing point ── */\n#compact-settings-modal {\n  z-index: 100;\n}\n#compact-settings-modal.hidden {\n  display: none;\n}\n#compact-settings-modal .cs-backdrop {\n  background: var(--backdrop);\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n}\n#compact-settings-modal .cs-card {\n  position: relative;\n  margin: auto;\n  max-height: 100%;\n  overflow: auto;\n  width: min(420px, 100%);\n  background: var(--bg);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 14px;\n  box-shadow: 0 8px 30px var(--key-shadow);\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n#compact-settings-modal h3 {\n  margin: 0;\n  font-size: var(--fs-lg);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n#compact-settings-modal .cs-hint {\n  margin: 0;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  line-height: 1.45;\n}\n/* The line that follows the EFFECTS of the two knobs. Empty = it takes no room. */\n#compact-settings-modal .cs-note:empty {\n  display: none;\n}\n#compact-settings-modal .cs-note {\n  color: var(--warn-soft);\n}\n#compact-settings-modal .cs-field {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n#compact-settings-modal .cs-field label {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n}\n/* Both knobs are SLIDERS. The landing one has 0 as its leftmost notch, which MEANS\n   AUTO, so the derived default and the explicit values share one control. */\n#compact-settings-modal .cs-inline {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n}\n#compact-settings-modal .cs-inline input[type=\"range\"] {\n  /* Sizing only; the appearance is the shared range rules' business. */\n  flex: 1 1 auto;\n  min-width: 0;\n  width: 100%;\n}\n#compact-settings-modal .cs-mini {\n  flex: 0 0 auto;\n  padding: 2px 8px;\n  font-size: var(--fs-sm);\n}\n/* Auto is ON = the landing point is the derived default (highlighted, never hidden). */\n#compact-settings-modal .cs-mini.is-on {\n  border-color: var(--accent);\n  color: var(--accent);\n}\n#compact-settings-modal .cs-scope {\n  margin-left: 6px;\n  font-size: var(--fs-sm);\n  font-weight: 400;\n  color: var(--muted-2);\n}\n/* The plan, as the host computes it: multi-line, never a layout jump. */\n#compact-settings-modal .cs-preview {\n  margin: 0;\n  padding: 8px;\n  background: var(--input-bg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  color: var(--muted-2);\n  font-size: var(--fs-sm);\n  line-height: 1.45;\n  white-space: pre-line;\n  min-height: 1em;\n  overflow-wrap: anywhere;\n}\n#compact-settings-modal .cs-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\n\n/* ── In-panel alert / confirm modal (same family as the name modal) ── */\n#alert-modal {\n  z-index: 110;\n}\n#alert-modal.hidden {\n  display: none;\n}\n#alert-modal .alert-backdrop {\n  background: var(--backdrop);\n  backdrop-filter: blur(4px);\n  -webkit-backdrop-filter: blur(4px);\n}\n#alert-modal .alert-card {\n  position: relative;\n  margin: auto;\n  max-height: 100%;\n  overflow: auto;\n  width: min(340px, 100%);\n  background: var(--bg);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 14px;\n  box-shadow: 0 8px 30px var(--key-shadow);\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n#alert-modal h3 {\n  margin: 0;\n  font-size: var(--fs-lg);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n#alert-modal .alert-message {\n  font-size: var(--fs-md);\n  color: var(--fg-dim);\n  line-height: 1.5;\n  word-wrap: break-word;\n  white-space: pre-wrap;\n}\n/* A question can also ASK for NUMBERS (the model limits of a model whose\n   host reports none). The rows reuse the Window/Output markup, so they look\n   and drag exactly like the sliders in the status card — one way to set a\n   value, wherever the panel asks for it. */\n#alert-modal .alert-fields {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n#alert-modal .alert-fields.hidden {\n  display: none;\n}\n#alert-modal .alert-field {\n  display: flex;\n  flex-direction: column;\n}\n#alert-modal .alert-field-label {\n  display: flex;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 6px;\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  margin-bottom: 2px;\n}\n/* wrap: a question can offer three answers (the session trash asks delete /\n   rewind / empty at once) and they must not spill out of the 340px card. */\n#alert-modal .alert-actions {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n#alert-ok.danger {\n  background: var(--error);\n}\n\n/* ── All-sessions manager (gear next to New session ──\n   Lists sessions of EVERY folder, most recent first. Red rows = the\n   session's folder is no longer available (open disabled until a valid\n   folder is picked). */\n#sessions-modal {\n  z-index: 60;\n}\n#sessions-modal.hidden {\n  display: none;\n}\n#sessions-modal .sm-backdrop {\n  background: var(--backdrop);\n}\n#sessions-modal .sm-card {\n  position: relative;\n  margin: auto;\n  width: min(680px, 100%);\n  max-height: 100%;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 18px 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  box-shadow: 0 8px 30px var(--modal-shadow);\n  font-size: var(--fs-lg);\n}\n#sessions-modal h3 {\n  margin: 0;\n  font-size: var(--fs-xl);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n#sessions-modal .sm-hint {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n}\n#sessions-manager-list {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  overflow-y: auto;\n  min-height: 140px;\n  flex: 1;\n}\n.sm-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 8px 10px;\n  border-radius: 8px;\n  background: var(--input-bg);\n  border: 1px solid var(--border);\n}\n.sm-row .sm-main {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n}\n.sm-row .sm-name {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-weight: 600;\n  font-size: var(--fs-lg);\n  color: var(--fg-strong);\n  min-width: 0;\n}\n.sm-row .sm-name > span:first-child {\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.sm-row .sm-tag {\n  flex: none;\n  font-size: var(--fs-xs);\n  color: var(--accent);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 1px 6px;\n}\n.sm-row .sm-meta {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n}\n.sm-row .sm-folder {\n  font-size: var(--fs-sm);\n  color: var(--muted-3);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  min-width: 0;\n  cursor: default;\n}\n.sm-row .sm-folder.missing {\n  color: var(--error);\n}\n/* Unknown (not set) folder is NEUTRAL, not red: only a KNOWN path that is\n   no longer available is a problem (red). */\n.sm-row .sm-folder.unset {\n  color: var(--muted-2);\n  font-style: italic;\n}\n.sm-actions {\n  display: inline-flex;\n  gap: 6px;\n  flex-shrink: 0;\n}\n.sm-actions button {\n  min-height: 1.54rem;\n  font-size: var(--fs-md);\n}\n.sm-actions button.secondary-ghost {\n  background: transparent;\n  border: 1px solid var(--border);\n  color: var(--fg);\n}\n.sm-actions button:disabled {\n  opacity: 0.3;\n  cursor: default;\n}\n#sessions-modal .sm-footer {\n  display: flex;\n  justify-content: flex-end;\n}\n/* DB compaction controls in the All-sessions modal footer. */\n.sm-vacuum {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  border-top: 1px solid var(--border);\n  padding-top: 10px;\n}\n.sm-vacuum-head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: var(--fs-sm);\n  color: var(--muted);\n}\n.sm-vacuum-head .spacer {\n  flex: 1;\n}\n/* The one card in a modal whose settings are LIVE: say so, because every other card\n   commits on Save (and its dialog says Close, not Cancel). */\n.sm-vacuum-live {\n  font-size: var(--fs-xs);\n  font-weight: 600;\n  line-height: 1;\n  padding: 2px 6px;\n  border-radius: 999px;\n  color: var(--accent);\n  background: var(--accent-tint-soft);\n  border: 1px solid var(--accent-line);\n  white-space: nowrap;\n}\n.sm-vacuum-slider {\n  display: grid;\n  grid-template-columns: 8.5rem 1fr 4.5rem;\n  align-items: center;\n  gap: 8px;\n  font-size: var(--fs-sm);\n  color: var(--muted);\n}\n.sm-vacuum-slider input[type=\"range\"] {\n  /* Sizing only (its grid column); the appearance is the shared range rules'. */\n  width: 100%;\n}\n.sm-vacuum-stats {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n.sm-vacuum-stats b {\n  color: var(--fg);\n}\n.sm-vacuum-stats .warn {\n  color: var(--accent);\n}\n/* Shared \"compact database\" modal (auto suggestion OR manual button). */\n#db-vacuum-modal {\n  z-index: 70;\n}\n#db-vacuum-modal.hidden {\n  display: none;\n}\n#db-vacuum-modal .dv-backdrop {\n  background: var(--backdrop);\n}\n#db-vacuum-modal .dv-card {\n  position: relative;\n  margin: auto;\n  max-height: 100%;\n  overflow: auto;\n  width: min(520px, 100%);\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 18px 20px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  box-shadow: 0 8px 30px var(--modal-shadow);\n  font-size: var(--fs-lg);\n}\n#db-vacuum-modal h3 {\n  margin: 0;\n  font-size: var(--fs-xl);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n#db-vacuum-modal .sm-hint {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n}\n.db-vacuum-stats {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  background: var(--input-bg);\n  border: 1px solid var(--border);\n  border-radius: 8px;\n  padding: 10px 12px;\n  font-size: var(--fs-sm);\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n.db-vacuum-stats b {\n  color: var(--fg);\n}\n.db-vacuum-stats .warn {\n  color: var(--accent);\n}\n.dv-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 8px;\n}\n/* Full-text search field above the list: filters to sessions whose MESSAGES\n   contain the term/phrase (FTS5 on the host). */\n#sessions-modal .sm-search {\n  display: flex;\n}\n/* Both search fields (main sessions list + all-sessions modal) share a look. */\n#sessions-search,\n#session-search {\n  width: 100%;\n  background: var(--surface-2);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 6px 8px;\n  font-size: var(--fs-lg);\n  outline: none;\n}\n#sessions-search:focus,\n#session-search:focus {\n  border-color: var(--accent);\n}\n/* Main sessions list: the search sits between the header and the list. */\n#session-search-row {\n  padding: 0 8px 6px;\n}\n#session-search-row.hidden {\n  display: none;\n}\n/* Per-row match excerpt: the matched terms are wrapped in [...] by FTS5 and\n   rendered in the accent color. */\n.sm-row .sm-snippet {\n  font-size: var(--fs-sm);\n  color: var(--muted-2);\n  overflow-wrap: anywhere;\n}\n.sm-row .sm-snippet b {\n  color: var(--accent);\n  font-weight: 600;\n}\n.sm-empty {\n  padding: 18px;\n  text-align: center;\n  color: var(--muted);\n  font-size: var(--fs-lg);\n}\n/* Main sessions list: no-match hint. */\n#sessions .empty.no-match {\n  font-style: italic;\n}\n\n/* ── \"Select model\" modal (filterable, provider tree preserved) ── */\n#model-modal {\n  z-index: 70;\n}\n#model-modal.hidden {\n  display: none;\n}\n#model-modal .mm-backdrop {\n  background: var(--backdrop);\n}\n#model-modal .mm-card {\n  position: relative;\n  margin: auto;\n  width: min(560px, 100%);\n  max-height: 100%;\n  background: var(--bg, #1e1e1e);\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 16px 18px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  box-shadow: 0 8px 30px var(--modal-shadow);\n  font-size: var(--fs-lg);\n}\n#model-modal .mm-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n#model-modal .mm-footer {\n  display: flex;\n  justify-content: flex-end;\n}\n#model-modal h3 {\n  margin: 0;\n  font-size: var(--fs-xl);\n  font-weight: 700;\n  color: var(--fg-strong);\n}\n#model-modal .mm-search {\n  display: flex;\n}\n/* Discreet warning: the models.dev fallback is unreachable and some model is\n   missing a limit (the alert is NOT a modal — it is a soft fallback miss). */\n.mm-warn {\n  font-size: var(--fs-sm);\n  color: var(--warn-soft);\n  line-height: 1.35;\n}\n.mm-warn.hidden {\n  display: none;\n}\n.warn-badge {\n  color: var(--warn-soft);\n  font-size: var(--fs-sm);\n  margin-left: 2px;\n}\n.warn-badge.hidden {\n  display: none;\n}\n#model-search {\n  width: 100%;\n  background: var(--surface-2);\n  color: var(--fg);\n  border: 1px solid var(--border);\n  border-radius: 6px;\n  padding: 6px 8px;\n  font-size: var(--fs-lg);\n  outline: none;\n}\n#model-search:focus {\n  border-color: var(--accent);\n}\n#model-list {\n  display: grid;\n  grid-template-columns: 1fr max-content max-content max-content 1.1rem;\n  column-gap: 6px;\n  row-gap: 5px;\n  align-items: center;\n  align-content: start;\n  overflow-y: auto;\n  min-height: 160px;\n  flex: 1;\n}\n/* Full-width items: the provider header + any single-row message spans every\n   column (only the model rows participate in the value columns). */\n#model-list .mm-provider,\n#model-list .mm-error,\n#model-list .mm-empty {\n  grid-column: 1 / -1;\n}\n/* Provider header: the tree is PRESERVED when filtering (only matching\n   models remain, empty providers drop out). */\n.mm-provider {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-top: 6px;\n  padding: 2px 4px;\n  font-size: var(--fs-sm);\n  font-weight: 700;\n  letter-spacing: 0.03em;\n  text-transform: uppercase;\n  color: var(--muted);\n  position: sticky;\n  top: 0;\n  background: var(--bg, #1e1e1e);\n}\n.mm-provider .mm-count {\n  font-weight: 500;\n  color: var(--muted-3);\n  text-transform: none;\n}\n/* Plain list rows: cancel the global \"key\" chrome (bevel/shadow/press).\n   Hover just lightens the background. Id-prefixed so it beats the\n   button:not(:disabled):hover filter. */\n#model-list .mm-model {\n  /* SUBGRID: the row spans the list's columns, so the context / \"out\" /\n     value columns share ONE width across rows (the widest value) while the\n     row keeps its own box (padding, hover, radius). */\n  grid-column: 1 / -1;\n  display: grid;\n  grid-template-columns: subgrid;\n  column-gap: 6px;\n  align-items: center;\n  width: 100%;\n  text-align: left;\n  padding: 9px 12px 9px 18px;\n  border-radius: 8px;\n  min-height: 0;\n  box-shadow: none;\n  background: transparent;\n  border: 1px solid transparent;\n  color: var(--fg);\n  cursor: pointer;\n  font-size: var(--fs-lg);\n  transition: background-color 0.12s;\n}\n#model-list .mm-model:hover {\n  background: var(--surface-2);\n  filter: none;\n  transform: none;\n}\n#model-list .mm-model:active {\n  transform: none;\n  box-shadow: none;\n  filter: none;\n}\n#model-list .mm-model:focus {\n  outline: none;\n  border-color: var(--accent);\n  background: var(--surface-2);\n}\n/* The current model: a light accent tint so it reads as \"selected\". */\n#model-list .mm-model.is-current {\n  background: var(--accent-tint);\n}\n#model-list .mm-model.is-current:hover {\n  background: var(--accent-tint-strong);\n}\n.mm-model .mm-model-name {\n  min-width: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.mm-model .mm-ctx {\n  font-size: var(--fs-sm);\n  color: var(--muted);\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n}\n.mm-model .mm-out-label {\n  text-align: right;\n}\n.mm-model.is-current {\n  color: var(--accent);\n  font-weight: 600;\n}\n.mm-model .mm-check {\n  color: var(--accent);\n  text-align: center;\n}\n.mm-error {\n  padding: 4px 8px 4px 20px;\n  font-size: var(--fs-sm);\n  color: var(--error);\n}\n.mm-empty {\n  padding: 18px;\n  text-align: center;\n  color: var(--muted);\n  font-size: var(--fs-lg);\n}\n";
